 674	    /// M17.5 F-61: `lower` selects the explicit dialect by this marker, and
 675	    /// `#!` is not `# `, so the heading exclusion never caught a literal
 676	    /// spelling it. Emitted compactly, it reparses as a different dialect.
 677	    #[test]
 678	    fn a_literal_spelling_the_dialect_marker_forces_explicit_emission() {
