 515	/// The rendered tables whose cells change when the lane runs. Blind pass 1 at
 516	/// ab5e109a (A09): relaxing the cell rule for every table on qualification was
 517	/// still far too much — ten of the twelve are derived from the packet and read
 518	/// the same before and after, so only these two may hold a value the packet
 519	/// does not declare.
 520	const RESULT_BEARING_TABLES: [&str; 3] = [
 521	    "| Family | Planned | Executed |",
 522	    "| Family | Relations and results |",
 523	    // The flip fills this one from `canaries.json` — the gate each canary
 524	    // violated, the observed failure text and `caught` — none of which the
 525	    // packet declares. Blind pass 1 at d8006c16 (A01).
 526	    "| Canary ID | Gate/conjunct |",
