 567	/// Strip markdown emphasis/code wrappers before comparing a cell to the
 568	/// closed verdict vocabulary. Formatting must not provide an escape hatch.
 569	fn normalized_markdown_cell(cell: &str) -> String {
 570	    let mut value = cell.trim();
 571	    loop {
 572	        let next = value
 573	            .strip_prefix('`')
 574	            .and_then(|inner| inner.strip_suffix('`'))
 575	            .or_else(|| {
 576	                value
 577	                    .strip_prefix("**")
 578	                    .and_then(|inner| inner.strip_suffix("**"))
 579	            })
 580	            .or_else(|| {
 581	                value
 582	                    .strip_prefix("__")
 583	                    .and_then(|inner| inner.strip_suffix("__"))
 584	            })
 585	            .or_else(|| {
 586	                value
 587	                    .strip_prefix('*')
 588	                    .and_then(|inner| inner.strip_suffix('*'))
 589	            })
 590	            .or_else(|| {
 591	                value
 592	                    .strip_prefix('_')
 593	                    .and_then(|inner| inner.strip_suffix('_'))
 594	            });
 595	        match next {
 596	            Some(inner) => value = inner.trim(),
 597	            None => break,
 598	        }
 599	    }
 600	    value.to_ascii_lowercase()
 601	}
