 648	/// While the packet is unqualified, a rendered table may carry only what the
 649	/// PACKET already declares — family names, predeclared counts, the declared
 650	/// fuzz budget — and otherwise must claim nothing. The flip is the only thing
 651	/// that may write a result, and it runs only on a qualified packet, so any
 652	/// other value in these tables is drift (A09).
 653	fn verify_markdown_tables(root: &Utf8Path, packet: &Packet) -> Result<()> {
 654	    let path = root.join("docs/execution/phase1-suite-review.md");
 655	    let text = fs::read_to_string(&path).with_context(|| format!("read {path}"))?;
 656	    // Blind pass 1 at ee646f8c (A09): this returned here for any qualified
 657	    // packet, on the reasoning that "the rest are bound by the packet digest
 658	    // this markdown carries". They are not. The digest binds the packet;
 659	    // editing a cell of this markdown leaves it untouched, so every table
 660	    // outside the review blocks went unchecked the moment provenance existed.
 661	    // Qualification changes exactly one thing: the flip may write results. So
 662	    // the shapes are checked either way, and only the value rule relaxes.
 663	    let qualified = packet.provenance.is_some();
 664	    let mut declared = BTreeSet::new();
 665	    for mutant in &packet.mutants {
 666	        declared.insert(mutant.family.clone());
 667	    }
 668	    for row in &packet.generated {
 669	        declared.insert(row.family.clone());
 670	        declared.insert(row.accepted.to_string());
 671	    }
 672	    let mut by_family = BTreeMap::<&str, usize>::new();
 673	    for mutant in &packet.mutants {
 674	        *by_family.entry(mutant.family.as_str()).or_default() += 1;
 675	    }
 676	    for count in by_family.values() {
 677	        declared.insert(count.to_string());
 678	    }
 679	    // The declared per-family fuzz budget, as the markdown spells it. ADR-0020
 680	    // §4 fixes 30 minutes per family; the packet names the targets, and the
 681	    // minutes are derived from the campaign, so the constant is the ADR's.
 682	    declared.insert("30 minutes".to_owned());
 683	    // The packet carries no `activation` field, so the markdown's activation
 684	    // column is editorial. It is a CLOSED vocabulary rather than free text: a
 685	    // new value is a visible decision, not drift.
 686	    for activation in ACTIVATION_VOCABULARY {
 687	        declared.insert((*activation).to_owned());
 688	    }
 689	    for requirement in &packet.requirements {
 690	        declared.insert(requirement.id.clone());
 691	    }
 692	    for test in &packet.tests {
 693	        declared.insert(test.id.clone());
 694	        declared.insert(test.name.clone());
 695	    }
 696	    // The canary table's ID column, now that the table is checked cell by
 697	    // cell. Every other column is NOT_RUN until the flip writes the run.
 698	    for canary in &packet.canaries {
 699	        declared.insert(canary.id.clone());
 700	    }
 701	    // No cell in ANY table may be a verdict while the packet is unqualified.
 702	    let lines = text.lines().collect::<Vec<_>>();
 703	    for (index, line) in lines.iter().enumerate() {
 704	        let trimmed = line.trim();
 705	        if !trimmed.starts_with('|') {
 706	            continue;
 707	        }
 708	        // A header row names its columns — "Executed", "Killed", "Survived"
 709	        // are column NAMES there, not claims. A header is the row a separator
 710	        // follows.
 711	        let is_header = lines.get(index + 1).is_some_and(|next| {
 712	            let next = next.trim();
 713	            next.starts_with('|')
 714	                && next
 715	                    .trim_matches('|')
 716	                    .chars()
 717	                    .all(|ch| matches!(ch, '-' | ':' | '|' | ' '))
 718	        });
 719	        if is_header {
 720	            continue;
 721	        }
 722	        for cell in trimmed.trim_matches('|').split('|') {
 723	            let value = normalized_markdown_cell(cell);
 724	            // A cell IS a verdict, or annotates a marker with one: both
 725	            // `| pass |` and `| NOT_RUN — passed |` claim a result the lane
 726	            // has not recorded (review of `a5c27fc`).
 727	            let smuggled = (value.starts_with("not_run") || value.starts_with("quarantined"))
 728	                && value
 729	                    .split(|ch: char| !ch.is_ascii_alphabetic())
 730	                    .any(|word| VERDICT_VOCABULARY.contains(&word));
 731	            anyhow::ensure!(
 732	                qualified || (!VERDICT_VOCABULARY.contains(&value.as_str()) && !smuggled),
 733	                "review markdown claims {value:?} while the packet is unqualified; only the \
 734	                 flip may write a verdict, and it runs on a qualified packet"
 735	            );
 736	        }
 737	    }
 738	    for header in RENDERED_TABLES {
 739	        let tables = markdown_tables(&text, header);
 740	        anyhow::ensure!(
 741	            !tables.is_empty(),
 742	            "review markdown has no table {header:?}"
 743	        );
 744	        // The HEADER's width, not the first row's: the finding was a row with
 745	        // surplus cells beneath a narrower header, which comparing rows to
 746	        // each other would not see. Each table brings its own.
 747	        for (width, rows) in tables {
 748	            for row in rows {
 749	                // Blind pass 1 at 9eca4f0 (A09): cell VALUES were checked but not
 750	                // how many there were, so a row could carry surplus cells beneath
 751	                // a narrower header and read as a different claim.
 752	                anyhow::ensure!(
 753	                    row.len() == width,
 754	                    "review markdown table {header:?} has a row of {} cells under a {width}-cell \
 755	                 header",
 756	                    row.len()
 757	                );
 758	                for cell in row {
 759	                    // Cells are markdown: an identifier is spelled in backticks.
 760	                    let value = cell.trim().trim_matches('`').trim();
 761	                    let renders_results = qualified && RESULT_BEARING_TABLES.contains(&header);
 762	                    anyhow::ensure!(
 763	                        renders_results || cell_claims_nothing(value) || declared.contains(value),
 764	                        "review markdown table {header:?} claims {value:?}, which the unqualified \
 765	                     packet does not declare; only the flip may write a result, and it runs \
 766	                     on a qualified packet"
 767	                    );
 768	                }
 769	            }
 770	        }
 771	    }
 772	    Ok(())
 773	}
