 836	/// Verify this repository's HAQP state for the named subcommand.
 837	pub fn verify_inventory_repo(root: &Utf8Path) -> Result<()> {
 838	    let packet = read_packet(root)?;
 839	    verify_packet_shape(&packet)?;
 840	    verify_requirement_sources(root, &packet)?;
 841	    verify_packet_statuses(&packet, inventory_statuses())?;
 842	    verify_markdown_surface(root, &packet)?;
 843	    verify_markdown_review_blocks(root, &packet)?;
 844	    verify_markdown_tables(root, &packet)?;
 845	    verify_oracle_independence(root)?;
