 858	    // verdict. F-65 moved the mutation plan's gates here; these are the rest
 859	    // that need no provenance, which is to say everything whose evidence is
 860	    // already in the tree.
 861	    verify_qualification_stage(&packet)?;
 862	    verify_locked_corpus_has_no_aliases(root)?;
 863	    verify_crash_terminal_states(&read_crash_evidence(root)?)?;
 864	    verify_review_receipts_inventory(root, &packet)?;
