 197	/// The body of `name` in `text`, using the lexical scanner to locate the
 198	/// definition and to find its matching structural closing brace.
 199	fn item_body<'a>(text: &'a str, name: &str) -> Option<&'a str> {
 200	    let needle = format!("fn {name}(");
 201	    let mut scanner = SourceScanner::default();
 202	    let mut offset = 0;
 203	    for line in text.split_inclusive('\n') {
 204	        if scanner.structural(line).contains(&needle) {
 205	            return item_body_from_start(text, offset);
 206	        }
 207	        offset += line.len();
 208	    }
 209	    None
 210	}
