   836	/// Verify this repository's HAQP state for the named subcommand.
   837	pub fn verify_inventory_repo(root: &Utf8Path) -> Result<()> {
   838	    let packet = read_packet(root)?;
   839	    verify_packet_shape(&packet)?;
   840	    verify_requirement_sources(root, &packet)?;
   841	    verify_packet_statuses(&packet, inventory_statuses())?;
   842	    verify_markdown_surface(root, &packet)?;
   843	    verify_markdown_review_blocks(root, &packet)?;
   844	    verify_markdown_tables(root, &packet)?;
   845	    verify_oracle_independence(root)?;
   846	    // M17.5 F-65: the mutation plan's gates lived only in the qualified path,
   847	    // which runs after the flip. A plan defect therefore cost a whole lane to
   848	    // discover, and `haq verify-inventory` — the command run by hand between
   849	    // lanes — never read the plan at all. AM-17.10's derivation and F-64's
   850	    // operator contract are checks on the PACKET, so they belong here too.
   851	    verify_mutant_source_coordinates(root, &packet)?;
   852	    verify_mutant_anchors_support_operators(root, &packet)?;
   853	    verify_mutant_killing_tests(root, &packet)?;
   854	    // Blind pass 2 at `ec045588` (A05, A09, A12): four checks were reachable
   855	    // only through `verify_qualified_repo`, which refuses before it starts
   856	    // unless the packet is already qualified — so at stage 1a they had never
   857	    // run against anything, and replacing each with `Ok(())` changed no
   858	    // verdict. F-65 moved the mutation plan's gates here; these are the rest
   859	    // that need no provenance, which is to say everything whose evidence is
   860	    // already in the tree.
   861	    verify_qualification_stage(&packet)?;
   862	    verify_locked_corpus_has_no_aliases(root)?;
   863	    verify_crash_terminal_states(&read_crash_evidence(root)?)?;
   864	    verify_review_receipts_inventory(root, &packet)?;
   865	    Ok(())
   866	}
