   896	/// Verify completed HAQP qualification evidence. Planned or NOT_RUN packet rows
   897	/// fail here; this is the command used by the M17 packet gate.
   898	pub fn verify_qualified_repo(root: &Utf8Path) -> Result<()> {
   899	    let packet = read_packet(root)?;
   900	    verify_packet_shape(&packet)?;
   901	    verify_requirement_sources(root, &packet)?;
   902	    verify_crash_boundary_scope(root, &packet)?;
   903	    verify_markdown_surface(root, &packet)?;
   904	    // Blind pass 1 at 5fb1b57 (A09): both of these ran on the inventory path
   905	    // only, so the path that judges a FLIPPED packet — the one that matters —
   906	    // accepted review cells disagreeing with their records and an oracle
   907	    // coupled to the production path it judges.
   908	    verify_markdown_review_blocks(root, &packet)?;
   909	    verify_markdown_tables(root, &packet)?;
   910	    verify_oracle_independence(root)?;
   911	    require_eq(
   912	        "qualification_state",
   913	        &packet.qualification_state,
   914	        "complete",
   915	    )?;
   916	    verify_mutant_source_coordinates(root, &packet)?;
   917	    verify_packet_statuses(
   918	        &packet,
   919	        PacketStatusExpectations {
   920	            // ADR-0021 stages the mutation requirement, so the expected mutant
   921	            // disposition is stage-dependent. Hardcoding `killed` here made
   922	            // HAQP-1a UNREACHABLE: leave mutants `predeclared` and this gate
   923	            // failed; mark one `killed` and verify_qualification_stage failed.
   924	            // The first version of ADR-0021 shipped with exactly that
   925	            // contradiction — the deadlock it existed to break, reintroduced
   926	            // one layer down.
   927	            mutant: if packet.qualification_stage == "1b" {
   928	                "resolved"
   929	            } else {
   930	                "predeclared"
   931	            },
   932	            canary: "caught",
   933	            generated: "pass",
   934	            crash: "pass",
   935	            review: "pass",
   936	        },
   937	    )?;
   938	    // M17.5 A6 / pass-2 #14,#15,#17,#19,#21: statuses are CLAIMS. Bind them to
   939	    // artifacts a run actually produced, or the whole gate is satisfiable by
   940	    // editing two files.
   941	    verify_provenance(root, &packet)?;
   942	    verify_concurrency_evidence(root, &packet)?;
   943	    verify_fuzz_evidence(root, &packet)?;
   944	    verify_locked_corpus_has_no_aliases(root)?;
   945	    verify_corpus_access_audit(root, &packet)?;
   946	    verify_crash_evidence(root, &packet)?;
   947	    verify_crash_replay(root, &packet)?;
   948	    let provenance = packet
   949	        .provenance
   950	        .as_ref()
   951	        .context("qualified campaign clock requires packet provenance")?;
   952	    verify_campaign_clock(root, &packet, Some(provenance))?;
   953	    verify_residual_risks(root, &packet)?;
   954	    verify_qualification_stage(&packet)?;
   955	    if packet.qualification_stage == "1b" {
