14734	/// Independent oracle for the interchange codec: structural round-trip,
14735	/// byte-stable re-encoding, and the promised shape counted in the encoded JSON
14736	/// by a parser that is not the codec (serde_json::Value), so a codec that
14737	/// silently dropped an operation could not certify itself.
14738	fn independent_oracle_interchange(
14739	    txn: &liminal_graph::Transaction,
14740	    decoded: &liminal_graph::Transaction,
14741	    once: &[u8],
14742	    twice: &[u8],
14743	    shape: InterchangeShape,
14744	) -> Result<Vec<u8>> {
14745	    // Do not serialize both sides with the product codec and compare those
14746	    // values. A serde field mutation would normalize expected and observed in
14747	    // the same way and make its own defect invisible (A02). Compare the
14748	    // decoded value through its public fields instead.
14749	    anyhow::ensure!(
14750	        txn.id == decoded.id,
14751	        "interchange field id changed during round trip"
14752	    );
14753	    anyhow::ensure!(
14754	        txn.parent == decoded.parent,
14755	        "interchange field parent changed during round trip"
14756	    );
14757	    anyhow::ensure!(
14758	        txn.meta.actor == decoded.meta.actor
14759	            && txn.meta.origin == decoded.meta.origin
14760	            && txn.meta.at == decoded.meta.at
14761	            && txn.meta.provenance == decoded.meta.provenance
14762	            && txn.meta.inverse == decoded.meta.inverse,
14763	        "interchange field meta changed during round trip"
14764	    );
14765	    anyhow::ensure!(
14766	        txn.ops.len() == decoded.ops.len(),
14767	        "interchange field ops length changed"
14768	    );
14769	    for (index, (expected, observed)) in txn.ops.iter().zip(&decoded.ops).enumerate() {
14770	        anyhow::ensure!(
14771	            expected == observed,
14772	            "interchange operation {index} changed during round trip"
14773	        );
14774	    }
14775	    anyhow::ensure!(once == twice, "interchange encoding is not byte-stable");
14776	    let value: serde_json::Value = serde_json::from_slice(once)?;
14777	    let ops = value["ops"]
14778	        .as_array()
14779	        .context("encoded transaction has no ops array")?;
14780	    let count = |key: &str| ops.iter().filter(|op| op.get(key).is_some()).count();
14781	    anyhow::ensure!(
14782	        count("create-node") == shape.nodes && count("add-relation") == shape.relations,
14783	        "encoded shape differs from the category's promise: {shape:?}"
14784	    );
14785	    // Blind pass 1 at f360e90 (A02): a renamed field round-trips through the
14786	    // same serde on both sides. The published schema is a closed key set.
14787	    // Sorted on this side: the pin is "no field added, removed or renamed",
14788	    // not the encoder's key order.
14789	    let keys = |value: &serde_json::Value| -> Vec<String> {
14790	        let mut keys: Vec<String> = value
14791	            .as_object()
14792	            .map(|map| map.keys().cloned().collect())
14793	            .unwrap_or_default();
14794	        keys.sort_unstable();
14795	        keys
14796	    };
14797	    anyhow::ensure!(
14798	        keys(&value) == ["id", "meta", "ops", "parent"],
14799	        "encoded transaction keys are not the published schema: {:?}",
14800	        keys(&value)
14801	    );
14802	    for op in ops {
14803	        if let Some(node) = op.pointer("/create-node/node") {
14804	            anyhow::ensure!(
14805	                keys(node) == ["flags", "id", "kind", "payload", "revision"],
14806	                "encoded node keys are not the published schema: {:?}",
14807	                keys(node)
14808	            );
14809	        }
14810	        if let Some(relation) = op.pointer("/add-relation/relation") {
14811	            anyhow::ensure!(
14812	                keys(relation)
14813	                    == [
14814	                        "flags", "id", "kind", "payload", "requires", "revision", "source",
14815	                        "target"
14816	                    ],
14817	                "encoded relation keys are not the published schema: {:?}",
14818	                keys(relation)
14819	            );
14820	        }
14821	    }
14822	    let payload_bytes = ops
14823	        .iter()
14824	        .filter_map(|op| op.pointer("/create-node/node/payload/text"))
14825	        .filter_map(serde_json::Value::as_str)
14826	        .map(str::len)
14827	        .max()
14828	        .unwrap_or(0);
14829	    anyhow::ensure!(
14830	        payload_bytes >= shape.payload_bytes_at_least,
14831	        "encoded payload {payload_bytes} bytes is under the category's floor"
14832	    );
14833	    Ok(once.to_vec())
14834	}
