14355	    // whatever the category, so a formatter that lost support for nested or
14356	    // deep documents reclassified them as negatives and the run still reached
14357	    // its accepted target from the categories that still worked. Only the
14358	    // categories that DECLARE malformed input may be refused.
14359	    const REFUSABLE: [&str; 5] = [
14360	        "truncated",
14361	        "unterminated",
14362	        "control-byte",
14363	        "invalid-utf8",
14364	        "hostile",
14365	    ];
14366	    let category = rng.category("source/CST/formatting");
14367	    let token = rng.word();
14368	    let bytes = match category {
14369	        "empty" => Vec::new(),
14370	        "single-token" => token.as_bytes().to_vec(),
14371	        "whitespace" => b" \t\n".to_vec(),
14372	        "unicode" => format!("{token} βeta").into_bytes(),
14373	        "long-line" => format!("{}-{token}", token.repeat(64)).into_bytes(),
14374	        "truncated" => format!("{token} {{#").into_bytes(),
14375	        "unterminated" => format!("{token} {{#{token}").into_bytes(),
14376	        "nested" => format!("{token} {{#outer {{#{token}}}}}").into_bytes(),
14377	        "deep" => format!("{} {token}", "{#".repeat(24)).into_bytes(),
14378	        // Blind pass 1 at `2bba9071` (A01): `boundary-offset` renders two
14379	        // blocks with IDENTICAL text, which a constant hash satisfies — it
14380	        // passes the equal-text arm and never meets the other. This renders
14381	        // two blocks of DIFFERENT width, so a hash that ignores its bytes
14382	        // collides across them and the relation has both arms to check. A
14383	        // durable marker cannot be used for this: the formatter lifts `{#id}`
14384	        // into an attribute, which moves a word and reads as reordering.
14385	        "wide" => {
14386	            let row = |count: usize| {
14387	                (0..count)
14388	                    .map(|_| token.clone())
14389	                    .collect::<Vec<_>>()
14390	                    .join(" ")
14391	            };
14392	            format!("{}\n\n{}", row(32), row(16)).into_bytes()
14393	        }
14394	        "control-byte" => format!("{token}\x01{token}").into_bytes(),
14395	        "invalid-utf8" => vec![0xff, 0xfe],
14396	        "comment" => format!("{token} <!-- {token} -->").into_bytes(),
14397	        "escape" => format!(r"{token} \ {token}").into_bytes(),
14398	        // Blind pass 1 at `ec045588` (A01): every generated source held at
14399	        // most ONE coarse block, so the per-document hash relation F-60 added
14400	        // — equal text hashes alike, different text does not — had nothing to
14401	        // relate and a constant hash passed 100,000 cases. A blank line makes
14402	        // two blocks, and repeating the token makes them equal, which is the
14403	        // arm a constant hash satisfies and a text-blind one does not.
14404	        "boundary-offset" => format!("{token}\n\n{token}").into_bytes(),
14405	        "hostile" => format!("{token}\0\x7f").into_bytes(),
14406	        other => unreachable!("unknown source category {other}"),
14407	    };
14408	    let Ok(source) = String::from_utf8(bytes.clone()) else {
14409	        let basis = liminal_source::SourceBasis {
14410	            source: liminal_id::SourceId::from_name("haqp-generated"),
14411	            content_hash: liminal_id::ContentHash::of(&bytes),
14412	        };
14413	        anyhow::ensure!(
14414	            liminal_source::Utf8HolderView::from_bytes(basis, &bytes).is_err(),
14415	            "invalid-utf8 source unexpectedly entered Utf8HolderView"
14416	        );
14417	        return Ok(Case::Negative {
14418	            category,
14419	            witness: bytes,
14420	        });
14421	    };
14422	    // Out of domain: the compact surface has no all-whitespace document.
14423	    if source.trim().is_empty() {
14424	        return Ok(Case::Negative {
14425	            category,
14426	            witness: format!("whitespace-source:{source:?}").into_bytes(),
14427	        });
14428	    }
14429	    let basis = liminal_source::SourceBasis {
14430	        source: liminal_id::SourceId::from_name("haqp-generated"),
14431	        content_hash: liminal_id::ContentHash::of(source.as_bytes()),
14432	    };
14433	    let Ok(view) = liminal_source::Utf8HolderView::from_bytes(basis, source.as_bytes()) else {
14434	        return Ok(Case::Negative {
14435	            category,
14436	            witness: source.into_bytes(),
14437	        });
14438	    };
14439	    let cst = liminal_cst::parse(&view);
14440	    let emitted = cst.emit_lossless();
14441	    // Blind pass 1 at 9eca4f0 (A01): the campaign exercised `parse` only, so
14442	    // `coarse_parse` — the other public entry point, the one that must never
14443	    // reject — could return empty block metadata for every input and no
14444	    // generated case would notice.
14445	    let coarse = liminal_cst::coarse_parse(&source);
