14447	    let Ok(once) = fmt.format(&source) else {
14448	        anyhow::ensure!(
14449	            REFUSABLE.contains(&category),
14450	            "the formatter refused valid-domain category {category}: a refusal there is lost \
14451	             support, not a negative case (source {source:?})"
14452	        );
14453	        return Ok(Case::Negative {
14454	            category,
14455	            witness: source.into_bytes(),
14456	        });
14457	    };
14458	    let Ok(twice) = fmt.format(&once) else {
14459	        anyhow::ensure!(
14460	            REFUSABLE.contains(&category),
14461	            "the formatter refused its own output for valid-domain category {category}: \
14462	             formatting is not total there (source {source:?})"
14463	        );
14464	        return Ok(Case::Negative {
14465	            category,
14466	            witness: once.into_bytes(),
14467	        });
14468	    };
14469	    let witness = independent_oracle_source_cst(&source, &emitted, &once, &twice, &token, &coarse)?;
14470	    Ok(Case::Accepted { category, witness })
14471	}
