14473	/// Family 1 — graph/interchange codecs.
14474	///
14475	/// Metamorphic relation: **byte-canonical stability**. Re-serializing a value
14476	/// decoded from canonical bytes must reproduce those bytes exactly. The
14477	/// comparison is over BYTES, never the type's own `PartialEq`, so a broken
14478	/// `Eq` cannot make this pass (ADR-0020 §5).
14479	/// A valid transaction carrying exactly ONE defect, the one `category` names,
14480	/// in its first created node (A03). The untouched base must decode, and the
14481	/// mutated bytes must be refused with the error that defect produces -- so a
14482	/// refusal is attributable to the category rather than to the input merely not
14483	/// being a transaction.
14484	fn transaction_with_one_defect(category: &str, rng: &mut Rng) -> Result<Vec<u8>> {
14485	    let text = format!("{category}:{}", rng.word());
14486	    let (txn, _) = interchange_transaction("single-edge", rng, &text, false);
14487	    let base = serde_json::to_value(&txn)?;
14488	    anyhow::ensure!(
14489	        serde_json::from_value::<liminal_graph::Transaction>(base.clone()).is_ok(),
14490	        "graph negative {category}: the base transaction must decode before a defect is added"
14491	    );
14492	    let mut value = base;
14493	    let op = value["ops"]
14494	        .as_array_mut()
14495	        .and_then(|ops| ops.iter_mut().find(|op| op.get("create-node").is_some()))
14496	        .context("graph negative base has no create-node operation")?;
14497	    let create = op["create-node"]
14498	        .as_object_mut()
14499	        .context("create-node is not an object")?;
14500	    let (raw, expected_error) = match category {
14501	        "missing-node" => {
14502	            create.remove("node").context("create-node has no node")?;
14503	            (serde_json::to_vec(&value)?, "missing field `node`")
14504	        }
14505	        "unknown-kind" => {
14506	            create["node"]["kind"] = serde_json::json!("unknown");
14507	            (serde_json::to_vec(&value)?, "invalid type")
14508	        }
14509	        "cycle" | "external-value" | "comment" => {
14510	            create["node"]["payload"] = match category {
14511	                "cycle" => serde_json::json!({ "cycle": ["a", "b", "a"] }),
14512	                "external-value" => serde_json::json!({ "external-value": "source" }),
14513	                _ => serde_json::json!({ "comment": "note" }),
14514	            };
14515	            (serde_json::to_vec(&value)?, "unknown variant")
14516	        }
14517	        "duplicate-id" => {
14518	            // A JSON object cannot hold a key twice as a Value, so the second
14519	            // `id` is spliced into the serialized node text.
14520	            let node = serde_json::to_string(&create["node"])?;
14521	            let rest = node
14522	                .strip_prefix('{')
14523	                .context("serialized node is not an object")?;
14524	            // The id's SERIALIZED form, not its Display form: the first
14525	            // version spliced `NodeId`'s Display text (`n…`) and the codec
14526	            // refused it for a malformed UUID -- a second defect, caught by the
14527	            // attribution check below.
14528	            let second_id = serde_json::to_string(&liminal_id::NodeId::from_uuid(rng.uuid()))?;
14529	            let duplicated = format!(r#"{{"id":{second_id},{rest}"#);
14530	            create["node"] = serde_json::json!("__A03_NODE__");
14531	            let text = serde_json::to_string(&value)?.replace(r#""__A03_NODE__""#, &duplicated);
14532	            (text.into_bytes(), "duplicate field `id`")
14533	        }
14534	        other => anyhow::bail!("unknown graph negative category {other}"),
14535	    };
14536	    let error = serde_json::from_slice::<liminal_graph::Transaction>(&raw)
14537	        .err()
14538	        .with_context(|| format!("graph negative {category} decoded as a Transaction"))?
14539	        .to_string();
14540	    anyhow::ensure!(
14541	        error.contains(expected_error),
14542	        "graph negative {category} was refused for another reason: expected {expected_error:?}, got {error:?}"
14543	    );
14544	    Ok(raw)
14545	}
