14547	fn case_interchange(rng: &mut Rng) -> Result<Case> {
14548	    let category = rng.category("graph/interchange codecs");
14549	    let malformed = matches!(
14550	        category,
14551	        "empty"
14552	            | "duplicate-id"
14553	            | "missing-node"
14554	            | "cycle"
14555	            | "unknown-kind"
14556	            | "external-value"
14557	            | "comment"
14558	            | "truncated-json"
14559	            | "invalid-json"
14560	            | "hostile"
14561	    );
14562	    if malformed {
14563	        // Blind pass 1 at `51bcc0b3` (A03): negatives were bare Node JSON checked
14564	        // with `from_slice::<Node>`, while the codec's unit is a Transaction --
14565	        // the positive half moved to Transaction under A07 and this half was
14566	        // left behind. A Transaction rejects a bare Node for being the wrong
14567	        // shape, not for the defect the category names, so no negative tested
14568	        // the codec's handling of a malformed transaction. Structural
14569	        // categories now carry exactly one defect inside an otherwise valid
14570	        // transaction, and the codec must reject it with the error that defect
14571	        // produces. Byte-level categories are malformed for any type already.
14572	        let raw = match category {
14573	            "empty" => Vec::new(),
14574	            "truncated-json" => format!(r#"{{"category":"{category}""#).into_bytes(),
14575	            "invalid-json" => {
14576	                let mut bytes = format!("{category}\0").into_bytes();
14577	                bytes.push(0xff);
14578	                bytes
14579	            }
14580	            "hostile" => vec![0, 0xff, 0x7f],
14581	            structural => transaction_with_one_defect(structural, rng)?,
14582	        };
14583	        anyhow::ensure!(
14584	            serde_json::from_slice::<liminal_graph::Transaction>(&raw).is_err(),
14585	            "graph negative category {category} unexpectedly decoded as a Transaction"
14586	        );
14587	        let witness = if raw.is_empty() {
14588	            format!("{category}:empty").into_bytes()
14589	        } else {
14590	            raw
14591	        };
14592	        return Ok(Case::Negative { category, witness });
14593	    }
14594	    // Blind pass 1 at 612cbcc (A07): every accepted category built one Node
14595	    // with the category's name leaked into its payload, and a Node is not even
14596	    // the codec's unit — the fuzz target decodes a Transaction. Each category
14597	    // now builds the transaction shape it names, and the oracle counts that
14598	    // shape in the encoded JSON independently of the codec's own equality.
14599	    let text = format!("{category}:{}", rng.word());
14600	    let durable = rng.below(2) == 1;
14601	    if matches!(category, "single-node") && durable && text.trim().is_empty() {
14602	        return Ok(Case::Discarded {
14603	            category,
14604	            witness: format!("durable-without-payload:{text:?}").into_bytes(),
14605	        });
14606	    }
14607	    let (txn, shape) = interchange_transaction(category, rng, &text, durable);
14608	    let once = serde_json::to_vec(&txn)?;
14609	    let decoded: liminal_graph::Transaction = serde_json::from_slice(&once)?;
14610	    let twice = serde_json::to_vec(&decoded)?;
14611	    let witness = independent_oracle_interchange(&txn, &decoded, &once, &twice, shape)?;
14612	    Ok(Case::Accepted { category, witness })
14613	}
