14615	/// The node and relation counts a category promises.
14616	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
14617	struct InterchangeShape {
14618	    nodes: usize,
14619	    relations: usize,
14620	    payload_bytes_at_least: usize,
14621	}
