14623	/// A transaction with the shape its category names: `single-edge` is two nodes
14624	/// and one relation, `dag` a diamond, `wide` a root with eight children, `deep`
14625	/// a chain of twelve, `large-payload` one node carrying 64 KiB of text.
14626	fn interchange_transaction(
14627	    category: &str,
14628	    rng: &mut Rng,
14629	    text: &str,
14630	    durable: bool,
14631	) -> (liminal_graph::Transaction, InterchangeShape) {
14632	    use liminal_graph::{
14633	        Node, NodeFlags, Operation, Origin, PayloadRef, Relation, RelationFlags, Target,
14634	        Transaction, TxnMeta,
14635	    };
14636	    let node = |rng: &mut Rng, payload: PayloadRef, durable: bool| Node {
14637	        id: liminal_id::NodeId::from_uuid(rng.uuid()),
14638	        kind: liminal_graph::KindId(u32::try_from(rng.below(8)).expect("kind fits")),
14639	        payload,
14640	        revision: liminal_id::RevisionId(rng.below(1_000)),
14641	        flags: if durable {
14642	            NodeFlags::HAS_DURABLE_ID
14643	        } else {
14644	            NodeFlags::default()
14645	        },
14646	    };
14647	    let relation =
14648	        |rng: &mut Rng, source: liminal_id::NodeId, target: liminal_id::NodeId| Relation {
14649	            id: liminal_id::RelationId::from_uuid(rng.uuid()),
14650	            source,
14651	            target: Target::Node(target),
14652	            kind: liminal_graph::KindId(u32::try_from(rng.below(8)).expect("kind fits")),
14653	            payload: PayloadRef::None,
14654	            revision: liminal_id::RevisionId(0),
14655	            flags: RelationFlags(0),
14656	            requires: None,
14657	        };
14658	    let (nodes, edges, payload_floor): (Vec<Node>, Vec<(usize, usize)>, usize) = match category {
14659	        "single-edge" => (
14660	            vec![
14661	                node(rng, PayloadRef::Text(text.to_owned()), durable),
14662	                node(rng, PayloadRef::None, false),
14663	            ],
14664	            vec![(0, 1)],
14665	            0,
14666	        ),
14667	        "dag" => (
14668	            (0..4).map(|_| node(rng, PayloadRef::None, false)).collect(),
14669	            vec![(0, 1), (0, 2), (1, 3), (2, 3)],
14670	            0,
14671	        ),
14672	        "wide" => (
14673	            (0..9).map(|_| node(rng, PayloadRef::None, false)).collect(),
14674	            (1..9).map(|child| (0, child)).collect(),
14675	            0,
14676	        ),
14677	        "deep" => (
14678	            (0..12)
14679	                .map(|_| node(rng, PayloadRef::None, false))
14680	                .collect(),
14681	            (0..11).map(|index| (index, index + 1)).collect(),
14682	            0,
14683	        ),
14684	        "large-payload" => (
14685	            vec![node(
14686	                rng,
14687	                PayloadRef::Text(text.repeat(65_536 / text.len().max(1) + 1)),
14688	                durable,
14689	            )],
14690	            Vec::new(),
14691	            65_536,
14692	        ),
14693	        // `single-node` and every category the seed table lists without a
14694	        // dedicated shape.
14695	        _ => {
14696	            let payload = if rng.below(4) == 0 {
14697	                PayloadRef::None
14698	            } else {
14699	                PayloadRef::Text(text.to_owned())
14700	            };
14701	            (vec![node(rng, payload, durable)], Vec::new(), 0)
14702	        }
14703	    };
