14720	        id: liminal_id::TransactionId::from_uuid(rng.uuid()),
14721	        parent: liminal_id::GraphRevisionId(rng.below(1_000)),
14722	        meta: TxnMeta {
14723	            actor: None,
14724	            origin: Origin::Human,
14725	            at: liminal_id::Timestamp(i64::try_from(rng.below(1_000_000)).expect("fits")),
14726	            provenance: None,
14727	            inverse: None,
14728	        },
14729	        ops,
14730	    };
