14812	                keys(relation)
14813	                    == [
14814	                        "flags", "id", "kind", "payload", "requires", "revision", "source",
14815	                        "target"
14816	                    ],
14817	                "encoded relation keys are not the published schema: {:?}",
14818	                keys(relation)
