15211	            revision: liminal_id::PublicationId::from_uuid(rng.uuid()),
15212	        },
15213	        "federated" => BasisPerspective::Federated {
15214	            domain: liminal_id::FederationId::from_uuid(rng.uuid()),
15215	            frontier: CausalFrontier(vec![
15216	                u8::try_from(rng.below(255)).expect("frontier byte fits"),
15217	            ]),
15218	        },
15219	        _ => BasisPerspective::DurableOnly,
15220	    };
