15222	        transaction: liminal_id::TransactionId::from_uuid(rng.uuid()),
15223	        perspective,
15224	        components: if category == "empty-basis" {
15225	            BTreeMap::new()
15226	        } else {
15227	            BTreeMap::from([(
15228	                liminal_revision::graph_key(),
15229	                BasisComponent::GraphSnapshot {
15230	                    revision: liminal_id::GraphRevisionId(rng.below(10_000)),
15231	                },
15232	            )])
