15241	    // keep a rare out-of-domain probe so the discard path stays exercised.
15242	    let read_count = if category == "empty-basis" || rng.below(384) == 0 {
15243	        0
15244	    } else {
15245	        1 + rng.below(5)
15246	    };
15247	    let mut deps = ComponentDeps::default();
15248	    let mut expected = BTreeSet::new();
15249	    for _ in 0..read_count {
15250	        let key = liminal_id::JurisdictionKey::Path(liminal_id::PathId(
15251	            format!("{category}/{}", rng.word()).into(),
15252	        ));
15253	        deps.record(key.clone());
15254	        expected.insert(key);
15255	    }
15256	    if malformed {
15257	        let key = liminal_id::JurisdictionKey::Path(liminal_id::PathId(
15258	            format!("{category}/__haqp_negative").into(),
15259	        ));
15260	        deps.record(key.clone());
15261	        let invalidated = deps.invalidated_by(&key);
15262	        let raw = match category {
15263	            "truncated" => b"{".to_vec(),
15264	            "hostile" => vec![0xff, 0x00, 0x7f],
15265	            "invalid-token" => br#"{"perspective":"unknown"}"#.to_vec(),
15266	            "unknown-perspective" => br#"{"perspective":{"future":true}}"#.to_vec(),
15267	            _ => unreachable!("malformed invalidation category {category}"),
15268	        };
