15274	            category,
15275	            witness: [
15276	                format!("basis-negative:{category}:{invalidated:?}:").into_bytes(),
15277	                raw,
15278	                basis_witness,
15279	            ]
15280	            .concat(),
15281	        });
15282	    }
15283	    // Out of domain: nothing was read, so invalidation is vacuous.
15284	    if expected.is_empty() {
15285	        return Ok(Case::Negative {
15286	            category,
15287	            witness: [b"vacuous-invalidation:".to_vec(), basis_witness].concat(),
15288	        });
15289	    }
