15291	    // Select a negative witness outside the generated read set. A random
15292	    // `unread/<word>` can collide with a legitimate read key, making the only
15293	    // negative assertion disappear exactly when the generator hits that case.
15294	    let unrelated = (0..u32::MAX)
15295	        .map(|index| {
15296	            liminal_id::JurisdictionKey::Path(liminal_id::PathId(
15297	                format!("unread/__haqp_negative_{index}").into(),
15298	            ))
15299	        })
15300	        .find(|candidate| !expected.contains(candidate))
15301	        .expect("finite generated read set leaves a negative witness");
