15351	/// Run the five families and return their evidence rows plus per-family
15352	/// wall-clock timings.
15353	///
15354	/// The timings are returned SEPARATELY rather than embedded in the rows on
15355	/// purpose: the rows are the hashable artifact and must be a pure function of
15356	/// the seed and the code under test, while the timings are telemetry for the
15357	/// operator (M17.5 pass-2 #18).
15358	///
15359	/// The case-count guard is a separate function so its BOUNDARIES are testable:
15360	/// `>` -> `>=` at the safety limit can only be discriminated by a case that
15361	/// runs at exactly 10,000,000, which no test can afford. Extracting the
15362	/// predicate makes the boundary checkable in microseconds (M17.5 F-30).
15363	/// Reject a case count that is zero or beyond the safety limit.
15364	fn validate_case_count(cases: u64) -> Result<()> {
15365	    if cases == 0 {
15366	        anyhow::bail!("generated case count must be positive");
15367	    }
15368	    if cases > 10_000_000 {
15369	        anyhow::bail!("generated case count exceeds safety limit: {cases} > 10000000");
15370	    }
15371	    Ok(())
15372	}
