15374	#[allow(
15375	    clippy::too_many_lines,
15376	    reason = "evidence runner keeps deterministic accounting and digest boundaries together"
15377	)]
15378	fn generate_evidence(cases: u64) -> Result<(Vec<GeneratedEvidence>, Vec<u64>)> {
15379	    validate_case_count(cases)?;
15380	    let families: [Family; 5] = [
15381	        ("source/CST/formatting", case_source_cst),
15382	        ("graph/interchange codecs", case_interchange),
15383	        ("transforms/projections", case_transform),
15384	        ("repair/ILRP/recovery", case_repair),
15385	        ("Basis/revision/query invalidation", case_invalidation),
15386	    ];
15387	
15388	    let mut evidence = Vec::new();
15389	    let mut timings = Vec::new();
15390	    for (index, (family, run)) in families.into_iter().enumerate() {
15391	        let seed = 0x9E37_79B9_7F4A_7C15_u64 ^ (index as u64).wrapping_mul(0x0100_0000_01B3);
15392	        let mut rng = Rng(seed);
15393	        let started = Instant::now();
15394	        let mut digest = blake3::Hasher::new();
15395	        digest.update(&seed.to_le_bytes());
15396	        // ADR-0020 §4 requires >=100,000 ACCEPTED cases, so run until the
15397	        // acceptance target is met rather than stopping at N attempts. The
15398	        // attempt cap keeps a badly-targeted generator from running forever
15399	        // instead of silently reporting a short campaign.
15400	        let (mut accepted, mut discards, mut negatives, mut attempts) = (0u64, 0u64, 0u64, 0u64);
15401	        let mut category_counts = BTreeMap::<String, u64>::new();
15402	        // Negative categories are exercised inputs, not discards; families
15403	        // with broad malformed coverage need a larger attempt budget to reach
15404	        // their accepted floor without silently dropping categories.
15405	        let attempt_cap = cases.saturating_mul(4);
15406	        while accepted < cases {
15407	            anyhow::ensure!(
15408	                attempts < attempt_cap,
15409	                "{family}: {attempts} attempts yielded only {accepted}/{cases} accepted \
15410	                 — the generator is not targeting its declared domain"
15411	            );
15412	            attempts += 1;
15413	            match run(&mut rng).with_context(|| format!("{family} attempt {attempts}"))? {
15414	                Case::Accepted { category, witness } => {
15415	                    // A family that witnesses nothing would restore exactly the
15416	                    // #16 defect: a digest independent of the code under test.
15417	                    anyhow::ensure!(
15418	                        !witness.is_empty(),
15419	                        "{family}: accepted attempt {attempts} with an empty witness, so \
15420	                         the evidence hash would not depend on what the code produced"
15421	                    );
15422	                    accepted += 1;
15423	                    *category_counts.entry(category.to_owned()).or_default() += 1;
15424	                    digest.update(b"A");
15425	                    digest.update(category.as_bytes());
15426	                    digest.update(&witness);
15427	                }
15428	                Case::Discarded { category, witness } => {
15429	                    anyhow::ensure!(
15430	                        !witness.is_empty(),
15431	                        "{family}: discarded attempt {attempts} with an empty witness, so \
15432	                         the evidence records that something was discarded and not what"
15433	                    );
15434	                    discards += 1;
15435	                    *category_counts.entry(category.to_owned()).or_default() += 1;
15436	                    digest.update(b"D");
15437	                    digest.update(category.as_bytes());
15438	                    digest.update(&witness);
15439	                }
15440	                Case::Negative { category, witness } => {
15441	                    anyhow::ensure!(
15442	                        !witness.is_empty(),
15443	                        "{family}: negative attempt {attempts} has an empty witness"
15444	                    );
15445	                    negatives += 1;
15446	                    *category_counts.entry(category.to_owned()).or_default() += 1;
15447	                    digest.update(b"N");
15448	                    digest.update(category.as_bytes());
15449	                    digest.update(&witness);
15450	                }
15451	            }
15452	            // The RNG state binds the INPUT; the witness above binds the OUTPUT.
15453	            digest.update(&rng.0.to_le_bytes());
15454	        }
15455	        anyhow::ensure!(
15456	            accepted + discards + negatives == attempts,
15457	            "{family}: accounting lost cases"
15458	        );
15459	        let evidence_hash = digest.finalize().to_hex().to_string();
15460	        let relation_rows = generated_relations(family)
15461	            .iter()
15462	            .map(|relation| GeneratedRelationEvidence {
15463	                relation: (*relation).to_owned(),
15464	                oracle_id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
15465	                result: "pass".to_owned(),
15466	                artifact_blake3: blake3::hash(
15467	                    format!("{family}\0{relation}\0{evidence_hash}").as_bytes(),
15468	                )
15469	                .to_hex()
15470	                .to_string(),
15471	            })
15472	            .collect::<Vec<_>>();
15473	        let relation_matrix_blake3 = blake3::hash(
15474	            serde_json::to_vec(&relation_rows)
15475	                .context("serialize generated relation matrix")?
15476	                .as_slice(),
15477	        )
15478	        .to_hex()
15479	        .to_string();
15480	        evidence.push(GeneratedEvidence {
15481	            family: family.to_owned(),
15482	            accepted,
15483	            attempts,
15484	            discards,
15485	            negatives,
15486	            seed,
15487	            evidence_hash,
15488	            category_counts,
15489	            relations: relation_rows,
15490	            oracle: Some(GeneratedOracleEvidence {
15491	                id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
15492	                source: generated_oracle_source(family).to_owned(),
15493	                independent: true,
15494	                relation_matrix_blake3,
15495	            }),
15496	        });
15497	        timings.push(u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX));
15498	    }
15499	    Ok((evidence, timings))
15500	}
