2888	/// The record's claims are what the retained answer says (F-92, blind pass 1
2889	/// at `088ddeec`, A12).
2890	///
2891	/// The raw answer and the structured claims were each hashed, and nothing
2892	/// compared them. A record could retain a real answer and carry different
2893	/// attempts, findings or verdict, with every digest true. The runner builds
2894	/// each claim as `redact_deep(parse_json(raw)[field])`
2895	/// (`scripts/haqp_blind_review.py`), so the gate re-derives it the same way
2896	/// from the retained answer, and requires the record to hold exactly that.
2897	fn verify_review_claims_are_the_answer(record_path: &Utf8Path) -> Result<()> {
2898	    let raw_path = record_path.with_extension("raw.txt");
2899	    let raw = fs::read_to_string(&raw_path)
2900	        .with_context(|| format!("{raw_path}: the raw answer must be retained"))?;
2901	    let answer = review_answer_json(&raw)
2902	        .with_context(|| format!("{raw_path}: the retained answer is not a review"))?;
2903	    let record: serde_json::Value = serde_json::from_slice(
2904	        &fs::read(record_path).with_context(|| format!("read {record_path}"))?,
2905	    )
2906	    .with_context(|| format!("parse {record_path}"))?;
2907	    for field in [
2908	        "attempts",
2909	        "findings",
2910	        "independently_reproduced",
2911	        "unresolved_verified_findings",
2912	        "result",
2913	    ] {
2914	        let said = match answer.get(field) {
2915	            Some(value) => value.clone(),
2916	            // `parsed.get("findings", [])`: the runner's one defaulted field.
2917	            None if field == "findings" => serde_json::Value::Array(Vec::new()),
2918	            None => serde_json::Value::Null,
2919	        };
2920	        // The count is copied, not redacted: it is not a string.
2921	        let expected = if field == "unresolved_verified_findings" {
2922	            said
2923	        } else {
2924	            redact_evidence_deep(&said)
2925	        };
2926	        let recorded = record.get(field).unwrap_or(&serde_json::Value::Null);
2927	        anyhow::ensure!(
2928	            *recorded == expected,
2929	            "review record `{field}` is not what the retained answer says; a record's \
2930	             claims are the reviewer's answer, not an edit of it"
2931	        );
2932	    }
2933	    Ok(())
2934	}
