2936	/// The reviewer's JSON, located as the runner's `parse_json` locates it: the
2937	/// whole text, or else the span from the first `{` to the last `}`.
2938	fn review_answer_json(raw: &str) -> Result<serde_json::Value> {
2939	    if let Ok(value) = serde_json::from_str::<serde_json::Value>(raw) {
2940	        return Ok(value);
2941	    }
2942	    let (Some(start), Some(end)) = (raw.find('{'), raw.rfind('}')) else {
2943	        anyhow::bail!("no JSON object in the answer");
2944	    };
2945	    anyhow::ensure!(start < end, "no JSON object in the answer");
2946	    Ok(serde_json::from_str(&raw[start..=end])?)
2947	}
