2951	fn redact_evidence_deep(value: &serde_json::Value) -> serde_json::Value {
2952	    match value {
2953	        serde_json::Value::String(text) => serde_json::Value::String(redact_evidence(text)),
2954	        serde_json::Value::Array(items) => {
2955	            serde_json::Value::Array(items.iter().map(redact_evidence_deep).collect())
2956	        }
2957	        serde_json::Value::Object(map) => serde_json::Value::Object(
2958	            map.iter()
2959	                .map(|(key, item)| (key.clone(), redact_evidence_deep(item)))
2960	                .collect(),
