3067	fn rulings(root: &Utf8Path) -> Result<Vec<Ruling>> {
3068	    let registry_path = root.join(RULING_REGISTRY);
3069	    let registry: RulingRegistry = serde_json::from_slice(
3070	        &fs::read(&registry_path).with_context(|| format!("read {registry_path}"))?,
3071	    )
3072	    .with_context(|| format!("parse {registry_path}"))?;
3073	    anyhow::ensure!(
3074	        registry.schema_version == 1,
3075	        "{RULING_REGISTRY}: unsupported schema_version {}",
3076	        registry.schema_version
3077	    );
3078	    let dir = root.join("docs/execution/rulings");
3079	    anyhow::ensure!(dir.is_dir(), "docs/execution/rulings is missing");
3080	    let mut files = fs::read_dir(dir.as_std_path())?
3081	        .map(|entry| entry.map(|e| e.path()))
3082	        .collect::<std::io::Result<Vec<_>>>()?;
3083	    files.sort();
3084	    let actual_files = files
3085	        .iter()
3086	        .filter(|file| file.extension().is_some_and(|ext| ext == "md"))
3087	        .map(|file| {
3088	            Utf8PathBuf::from_path_buf(file.clone())
3089	                .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?
3090	                .strip_prefix(root)
3091	                .map(ToOwned::to_owned)
3092	                .map_err(anyhow::Error::from)
3093	        })
3094	        .collect::<Result<BTreeSet<_>>>()?;
3095	    let mut registered_files = BTreeSet::new();
3096	    let mut registered_ids = BTreeSet::new();
3097	    for entry in &registry.rulings {
3098	        anyhow::ensure!(
3099	            registered_ids.insert(entry.id.as_str()),
3100	            "{RULING_REGISTRY}: duplicate ruling id {}",
3101	            entry.id
3102	        );
3103	        anyhow::ensure!(
3104	            registered_files.insert(entry.file.as_str()),
3105	            "{RULING_REGISTRY}: duplicate ruling file {}",
3106	            entry.file
3107	        );
3108	        validate_ruling_coordinate(&entry.target).with_context(|| {
3109	            format!("{RULING_REGISTRY}: ruling {} has invalid target", entry.id)
3110	        })?;
3111	        anyhow::ensure!(
3112	            entry.file.starts_with("docs/execution/rulings/")
3113	                && Path::new(&entry.file)
3114	                    .extension()
3115	                    .is_some_and(|extension| extension.eq_ignore_ascii_case("md"))
3116	                && canonical_relative_path(&entry.file),
3117	            "{RULING_REGISTRY}: invalid ruling file path {:?}",
3118	            entry.file
3119	        );
3120	    }
3121	    anyhow::ensure!(
3122	        registered_files == actual_files.iter().map(|p| p.as_str()).collect(),
3123	        "{RULING_REGISTRY}: registered ruling files differ from docs/execution/rulings/*.md; registered={registered_files:?}, actual={actual_files:?}"
3124	    );
3125	    let mut out = Vec::new();
3126	    for file in files {
3127	        let file = Utf8PathBuf::from_path_buf(file)
3128	            .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
3129	        if file.extension() != Some("md") {
3130	            continue;
3131	        }
3132	        let relative_file = file.strip_prefix(root)?.to_string();
3133	        let registry_entry = registry
3134	            .rulings
3135	            .iter()
3136	            .find(|entry| entry.file == relative_file)
3137	            .with_context(|| {
3138	                format!("{RULING_REGISTRY}: unregistered ruling file {relative_file}")
3139	            })?;
3140	        let text = fs::read_to_string(&file)?;
3141	        let front = text
3142	            .strip_prefix("---\n")
3143	            .and_then(|rest| rest.split_once("\n---\n"))
3144	            .map(|(front, _)| front)
3145	            .with_context(|| format!("{file}: ruling has no front matter"))?;
3146	        let field = |key: &str| -> Result<String> {
3147	            let fields = front
3148	                .lines()
3149	                .filter_map(|line| line.strip_prefix(&format!("{key}: ")))
3150	                .collect::<Vec<_>>();
3151	            anyhow::ensure!(
3152	                fields.len() == 1,
3153	                "{file}: expected exactly one {key} field"
3154	            );
3155	            fields
3156	                .first()
3157	                .copied()
3158	                .map(|v| v.trim().trim_matches('"').to_owned())
3159	                .with_context(|| format!("{file}: ruling front matter lacks {key}"))
3160	        };
3161	        let excludes = field("claim_excludes").unwrap_or_default();
3162	        let requires = field("claim_requires")?;
3163	        anyhow::ensure!(
3164	            !requires.trim().is_empty(),
3165	            "{file}: ruling claim_requires is empty; a ruling that answers any claim in its \
3166	             class and coordinate clears defects it was never shown (A08)"
3167	        );
3168	        let id = field("id")?;
3169	        let target = field("target")?;
3170	        let status = field("status")?;
3171	        validate_ruling_coordinate(&target)
3172	            .with_context(|| format!("{file}: ruling target must be an exact coordinate"))?;
3173	        anyhow::ensure!(
3174	            id == registry_entry.id,
3175	            "{file}: ruling id differs from registry"
3176	        );
3177	        anyhow::ensure!(
3178	            target == registry_entry.target,
3179	            "{file}: ruling target differs from its authoritative registry coordinate"
3180	        );
3181	        anyhow::ensure!(
3182	            matches!(status.as_str(), "draft" | "ruled" | "withdrawn"),
3183	            "{file}: unsupported ruling status {status:?}"
3184	        );
3185	        out.push(Ruling {
3186	            id,
3187	            attack_class: field("attack_class")?,
3188	            target,
3189	            claim_requires: requires
3190	                .split(';')
3191	                .map(|phrase| phrase.trim().to_ascii_lowercase())
3192	                .filter(|phrase| !phrase.is_empty())
3193	                .collect(),
3194	            claim_excludes: excludes
3195	                .split(';')
3196	                .map(|phrase| phrase.trim().to_ascii_lowercase())
3197	                .filter(|phrase| !phrase.is_empty())
3198	                .collect(),
3199	            status,
3200	            file: relative_file,
3201	        });
3202	    }
3203	    Ok(out)
3204	}
