3206	fn validate_ruling_coordinate(target: &str) -> Result<()> {
3207	    let (path, line) = target
3208	        .rsplit_once(':')
3209	        .context("target is not a repository path:positive-line coordinate")?;
3210	    anyhow::ensure!(
3211	        canonical_relative_path(path) && !path.contains(':') && !path.contains('\\'),
3212	        "target path is not canonical"
3213	    );
3214	    anyhow::ensure!(
3215	        !line.is_empty()
3216	            && line.bytes().all(|byte| byte.is_ascii_digit())
3217	            && (line == "0" || !line.starts_with('0'))
3218	            && line.parse::<usize>().is_ok_and(|value| value > 0),
3219	        "target line must be a canonical positive decimal"
3220	    );
3221	    Ok(())
3222	}
