3224	fn canonical_relative_path(path: &str) -> bool {
3225	    !path.is_empty()
3226	        && !path.starts_with('/')
3227	        && Path::new(path)
3228	            .components()
3229	            .all(|component| matches!(component, Component::Normal(_)))
3230	        && path
3231	            .split('/')
3232	            .all(|component| !component.is_empty() && component != "." && component != "..")
3233	}
