3271	        serde_json::from_slice(&fs::read(record)?).with_context(|| format!("parse {record}"))?;
3272	    let in_force = rulings(root)?
3273	        .into_iter()
3274	        .filter(|ruling| ruling_in_force(root, ruling).unwrap_or(false))
3275	        .collect::<Vec<_>>();
