3279	/// The count, given the rulings already established to be in force. Split from
3280	/// the repository walk so the clearance rules can be exercised without a
3281	/// signing key: a rule the tests cannot reach is a rule nothing checks.
3282	fn effective_unresolved_findings(
3283	    in_force: &[Ruling],
3284	    value: &serde_json::Value,
3285	    record: &Utf8Path,
3286	) -> Result<u64> {
3287	    // Counted from each attempt's own flags, not through the findings list:
3288	    // a verified, reproduced attempt the reviewer forgot to list as a finding
3289	    // is still unresolved.
3290	    let mut unresolved = 0u64;
3291	    let mut cleared: BTreeMap<String, u64> = BTreeMap::new();
3292	    for attempt in value["attempts"].as_array().into_iter().flatten() {
3293	        let class = attempt["attack_class"].as_str().unwrap_or_default();
3294	        let target = attempt["target"].as_str().unwrap_or_default();
3295	        if attempt["classification"].as_str() != Some("verified_defect")
3296	            || !attempt["independently_reproduced"]
3297	                .as_bool()
3298	                .unwrap_or(false)
3299	            || attempt["resolved"].as_bool().unwrap_or(false)
3300	        {
3301	            continue;
3302	        }
3303	        let prose = format!(
3304	            "{} {}",
3305	            attempt["attempt"].as_str().unwrap_or_default(),
3306	            attempt["observed_result"].as_str().unwrap_or_default()
3307	        )
3308	        .to_ascii_lowercase();
3309	        // Blind pass 1 at c29bc0ea (A08): a ruling matched on class, file and
3310	        // prose substrings, so an unrelated defect in the same file whose
3311	        // wording happened to carry the required phrases was cleared in
3312	        // silence. Two things changed. A ruling that names a coordinate is
3313	        // held to it, not merely to the file. And a ruling clears at most one
3314	        // attempt per record: matching a second is evidence the phrases are
3315	        // too broad, and the answer to that is a refusal, not two clearances.
3316	        let matched = in_force
3317	            .iter()
3318	            .filter(|ruling| {
3319	                ruling.attack_class == class
3320	                    && ruling.target == target
3321	                    && ruling
3322	                        .claim_requires
3323	                        .iter()
3324	                        .all(|phrase| prose.contains(phrase.as_str()))
3325	                    && !ruling
3326	                        .claim_excludes
3327	                        .iter()
3328	                        .any(|phrase| prose.contains(phrase.as_str()))
3329	            })
3330	            .collect::<Vec<_>>();
3331	        for ruling in &matched {
3332	            *cleared.entry(ruling.id.clone()).or_insert(0u64) += 1;
3333	        }
3334	        if matched.is_empty() {
3335	            unresolved += 1;
3336	        }
3337	    }
3338	    for (id, count) in &cleared {
3339	        anyhow::ensure!(
3340	            *count <= 1,
3341	            "ruling {id} cleared {count} separate findings in {record}; a ruling \
3342	                 answers one claim, so phrases matching more than one are too \
3343	                 broad to stand"
3344	        );
3345	    }
3346	    Ok(unresolved)
3347	}
