3235	/// A ruling is in force when its status is `ruled` and the last commit that
3236	/// touched its file verifies against the pinned signers. A draft, an
3237	/// uncommitted edit, or an unsigned commit clears nothing.
3238	fn ruling_in_force(root: &Utf8Path, ruling: &Ruling) -> Result<bool> {
3239	    if ruling.status != "ruled" {
3240	        return Ok(false);
3241	    }
3242	    let signers = root.join(RULING_SIGNERS);
3243	    anyhow::ensure!(
3244	        signers.is_file(),
3245	        "{RULING_SIGNERS} is missing; a ruling cannot be verified against no signer"
3246	    );
3247	    let dirty = git_text(root, &["status", "--porcelain", "--", &ruling.file])?;
3248	    if !dirty.trim().is_empty() {
3249	        return Ok(false);
3250	    }
3251	    let commit = git_text(root, &["log", "-1", "--format=%H", "--", &ruling.file])?;
3252	    if commit.trim().is_empty() {
3253	        return Ok(false);
3254	    }
3255	    let verified = Command::new("git")
3256	        .current_dir(root)
3257	        .args(["-c", "gpg.format=ssh", "-c"])
3258	        .arg(format!("gpg.ssh.allowedSignersFile={signers}"))
3259	        .args(["verify-commit", commit.trim()])
3260	        .output()
3261	        .context("git verify-commit")?;
3262	    Ok(verified.status.success())
3263	}
