5600	        )?);
5601	        let error = rows.last().and_then(|row| {
5602	            (row.status == "error").then(|| {
5603	                (
5604	                    row.id.clone(),
5605	                    row.reason
5606	                        .clone()
5607	                        .unwrap_or_else(|| "unknown mutation error".to_owned()),
5608	                )
5609	            })
5610	        });
5611	        if let Some((id, reason)) = error {
5612	            reset_mutant_worktree(&worktree, &source_commit)?;
5613	            worktree_guard.remove()?;
