5639	fn ignored_test_names(root: &Utf8Path) -> BTreeSet<String> {
5640	    let mut names = BTreeSet::new();
5641	    let mut stack = vec![root.join("conformance"), root.join("crates")];
5642	    while let Some(dir) = stack.pop() {
5643	        let Ok(entries) = fs::read_dir(&dir) else {
5644	            continue;
5645	        };
5646	        for entry in entries.flatten() {
5647	            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
5648	                continue;
5649	            };
5650	            if path.is_dir() {
5651	                if path.file_name() != Some("target") {
5652	                    stack.push(path);
5653	                }
5654	            } else if path.extension() == Some("rs")
5655	                && let Ok(text) = fs::read_to_string(&path)
