5851	fn cfg_attribute_excludes(trimmed: &str) -> bool {
5852	    if !trimmed.starts_with("#[cfg(") {
5853	        return false;
5854	    }
5855	    if trimmed == "#[cfg(any())]" {
5856	        return true;
5857	    }
5858	    if trimmed == "#[cfg(test)]" {
5859	        return false;
5860	    }
5861	    if trimmed == "#[cfg(not(test))]" {
5862	        return true;
5863	    }
5864	    if trimmed == "#[cfg(unix)]" {
5865	        return !cfg!(unix);
5866	    }
5867	    if trimmed == "#[cfg(windows)]" {
5868	        return !cfg!(windows);
5869	    }
5870	    if trimmed.contains("target_os = \"linux\"") {
5871	        return !cfg!(target_os = "linux");
5872	    }
5873	    if trimmed.contains("target_os = \"windows\"") {
5874	        return !cfg!(target_os = "windows");
5875	    }
5876	    // Unknown predicates remain fail-closed: scanner cannot prove they are
5877	    // active on this host.
5878	    true
5879	}
