5543	/// Execute source patches in disposable git worktrees. This command writes only
5544	/// digests and statuses; raw test/model output never enters the repository.
5545	pub fn run_mutants_repo(root: &Utf8Path, ids: &[String], run_ignored: bool) -> Result<()> {
5546	    let packet = read_packet(root)?;
5547	    verify_packet_shape(&packet)?;
5548	    let dirt = source_dirt(root)?;
5549	    anyhow::ensure!(
5550	        dirt.is_empty(),
5551	        "mutant runner requires a clean SOURCE tree; dirty: {dirt:?}"
5552	    );
5553	    let source_commit = git_text(root, &["rev-parse", "HEAD"])?;
5554	    let lockfile_blake3 = hex_digest(&fs::read(root.join("Cargo.lock"))?);
5555	    let selected = if ids.is_empty() {
5556	        packet.mutants.iter().collect::<Vec<_>>()
5557	    } else {
5558	        let wanted = ids.iter().cloned().collect::<BTreeSet<_>>();
5559	        let selected = packet
5560	            .mutants
5561	            .iter()
5562	            .filter(|mutant| wanted.contains(&mutant.id))
5563	            .collect::<Vec<_>>();
5564	        let present = selected
5565	            .iter()
5566	            .map(|mutant| mutant.id.clone())
5567	            .collect::<BTreeSet<_>>();
5568	        anyhow::ensure!(
5569	            present.len() == wanted.len(),
5570	            "unknown mutant id(s): {:?}",
5571	            wanted.difference(&present).collect::<Vec<_>>()
5572	        );
5573	        selected
5574	    };
5575	
5576	    let ignored = ignored_test_names(root);
5577	    let scratch = liminal_scratch::ScratchDir::new("haq-mutants")?;
5578	    let worktree = scratch.path().to_owned();
5579	    let add = Command::new("git")
5580	        .current_dir(root)
5581	        .args(["worktree", "add", "--detach", "--quiet"])
5582	        .arg(&worktree)
5583	        .arg(&source_commit)
5584	        .output()?;
5585	    anyhow::ensure!(
5586	        add.status.success(),
5587	        "git worktree add failed: {}",
5588	        String::from_utf8_lossy(&add.stderr).trim()
5589	    );
5590	    let mut worktree_guard = WorktreeGuard::new(root, &worktree);
5591	
5592	    let mut rows = Vec::with_capacity(selected.len());
5593	    for mutant in selected {
5594	        rows.push(run_mutant_row(
5595	            &worktree,
5596	            &packet,
5597	            mutant,
5598	            &ignored,
5599	            run_ignored,
5600	        )?);
5601	        let error = rows.last().and_then(|row| {
5602	            (row.status == "error").then(|| {
5603	                (
5604	                    row.id.clone(),
5605	                    row.reason
5606	                        .clone()
5607	                        .unwrap_or_else(|| "unknown mutation error".to_owned()),
5608	                )
5609	            })
5610	        });
5611	        if let Some((id, reason)) = error {
5612	            reset_mutant_worktree(&worktree, &source_commit)?;
5613	            worktree_guard.remove()?;
5614	            anyhow::bail!("{id}: {reason}");
5615	        }
5616	        reset_mutant_worktree(&worktree, &source_commit)?;
5617	    }
5618	    worktree_guard.remove()?;
5619	    drop(scratch);
5620	
5621	    let evidence = MutantEvidence {
5622	        schema_version: "haqp-mutants-v1".to_owned(),
5623	        source_commit,
5624	        lockfile_blake3,
5625	        runner: "liminal-xtask haq mutants".to_owned(),
5626	        rows,
5627	    };
5628	    let path = root.join("conformance/haqp/evidence/mutants.json");
5629	    fs::create_dir_all(path.parent().expect("evidence parent"))?;
5630	    fs::write(&path, serde_json::to_vec_pretty(&evidence)?)?;
5631	    println!(
5632	        "mutant evidence written to {path}; rows={}",
5633	        evidence.rows.len()
5634	    );
