5664	/// An `#[ignore]` attribute applies to the next `fn` declaration.
5665	fn collect_ignored(text: &str, names: &mut BTreeSet<String>) {
5666	    let mut pending = false;
5667	    for line in text.lines() {
5668	        let trimmed = line.trim_start();
5669	        // A test is non-runnable if it is ignored OUTRIGHT, ignored
5670	        // CONDITIONALLY, or compiled out. All three cannot witness a kill, and
5671	        // only the first was recognised: `#[cfg_attr(unix, ignore)]` and
5672	        // `#[cfg(any())]` both vanish at run time while reading as live source.
5673	        if trimmed.starts_with("#[ignore")
5674	            || (trimmed.starts_with("#[cfg_attr(") && trimmed.contains("ignore"))
5675	            || trimmed.starts_with("#[cfg(any())]")
5676	        {
5677	            pending = true;
5678	            continue;
5679	        }
5680	        if let Some(rest) = trimmed.strip_prefix("fn ") {
5681	            if pending && let Some(name) = rest.split('(').next() {
5682	                names.insert(name.trim().to_owned());
5683	            }
5684	            pending = false;
5685	        }
5686	    }
5687	}
