5689	/// Blind pass 1 at aa00d41 (A10): mutation runs and the `#[ignore]` check both
5690	/// filter by a test's LEAF name, so two tests sharing a leaf make the filter
5691	/// ambiguous — an unrelated namesake could pass and certify a declared kill,
5692	/// or an ignored namesake could mask one. A leaf a mutant relies on must name
5693	/// exactly one runnable test in the tree.
5694	fn verify_killing_test_leaves_are_unambiguous(root: &Utf8Path, packet: &Packet) -> Result<()> {
5695	    let mut leaves: BTreeMap<String, Vec<String>> = BTreeMap::new();
5696	    let mut stack = vec![root.join("conformance"), root.join("crates")];
5697	    while let Some(dir) = stack.pop() {
5698	        let Ok(entries) = fs::read_dir(&dir) else {
5699	            continue;
5700	        };
5701	        for entry in entries.flatten() {
5702	            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
5703	                continue;
5704	            };
5705	            if path.is_dir() {
5706	                if path.file_name() != Some("target") {
5707	                    stack.push(path);
5708	                }
5709	            } else if path.extension() == Some("rs")
5710	                && let Ok(text) = fs::read_to_string(&path)
5711	            {
5712	                let mut local = BTreeMap::new();
5713	                collect_runnable_test_functions(&text, &mut local);
5714	                let where_ = path.strip_prefix(root).unwrap_or(&path).to_string();
5715	                for name in local.keys() {
5716	                    leaves.entry(name.clone()).or_default().push(where_.clone());
5717	                }
5718	            }
5719	        }
5720	    }
5721	    let declared = packet
5722	        .tests
5723	        .iter()
5724	        .map(|test| (test.id.as_str(), test.name.as_str()))
5725	        .collect::<BTreeMap<_, _>>();
5726	    for mutant in &packet.mutants {
5727	        for test_id in &mutant.killing_tests {
5728	            let Some(name) = declared.get(test_id.as_str()) else {
5729	                continue;
5730	            };
5731	            let leaf = name.rsplit("::").next().unwrap_or(name);
5732	            if let Some(files) = leaves.get(leaf)
5733	                && files.len() > 1
5734	            {
5735	                anyhow::bail!(
5736	                    "{} is killed by {test_id} ({name}), whose leaf {leaf:?} names {} tests \
5737	                     ({files:?}); a leaf the mutation run filters on must be unique, or a \
5738	                     namesake can certify the kill",
5739	                    mutant.id,
5740	                    files.len()
5741	                );
5742	            }
5743	        }
5744	    }
5745	    Ok(())
5746	}
