5248	        .chars()
5249	        .flat_map(|ch| match ch {
5250	            '\\' | '.' | '+' | '*' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '^' | '$' | '|' => {
5251	                vec!['\\', ch]
