5300	fn is_semantic_test_failure(test_name: &str, stdout: &[u8], stderr: &[u8]) -> bool {
5301	    let leaf = test_name.rsplit("::").next().unwrap_or(test_name);
5302	    let text = String::from_utf8_lossy(stdout);
5303	    let err = String::from_utf8_lossy(stderr);
5304	    // Require named-test and failure token on one line. This rejects launcher
5305	    // infrastructure prose such as "launcher FAILED before tests" instead of
5306	    // counting it as a semantic mutant kill.
5307	    [text.as_ref(), err.as_ref()].iter().any(|output| {
5308	        output
5309	            .lines()
5310	            .any(|line| line.trim_start().starts_with("FAIL [") && line.contains(leaf))
5311	    })
5312	}
