5318	fn run_mutant_row(
5319	    worktree: &Utf8Path,
5320	    packet: &Packet,
5321	    mutant: &Mutant,
5322	    ignored: &BTreeSet<String>,
5323	    run_ignored: bool,
5324	) -> Result<MutantEvidenceRow> {
5325	    let Some(patch) = mutant.patch.clone() else {
5326	        return Ok(MutantEvidenceRow {
5327	            id: mutant.id.clone(),
5328	            disposition: mutant.disposition.clone(),
5329	            status: "not-ready".to_owned(),
5330	            patch: None,
5331	            runnable_tests: Vec::new(),
5332	            baseline_exit_codes: Vec::new(),
5333	            failed_tests: Vec::new(),
5334	            exit_codes: Vec::new(),
5335	            stdout_blake3: Vec::new(),
5336	            stderr_blake3: Vec::new(),
5337	            reason: Some("no patch declared".to_owned()),
5338	            failure_class: None,
