5340	    };
5341	    let runnable = mutant
5342	        .killing_tests
5343	        .iter()
5344	        .filter_map(|test_id| packet.tests.iter().find(|test| &test.id == test_id))
5345	        .filter(|test| {
5346	            run_ignored
5347	                || !ignored.contains(test.name.rsplit("::").next().unwrap_or(test.name.as_str()))
5348	        })
5349	        .map(|test| (test.id.clone(), test.name.clone()))
5350	        .collect::<Vec<_>>();
