5352	        return Ok(MutantEvidenceRow {
5353	            id: mutant.id.clone(),
5354	            disposition: mutant.disposition.clone(),
5355	            status: "not-runnable".to_owned(),
5356	            patch: Some(patch),
5357	            runnable_tests: Vec::new(),
