5371	        })
5372	        .collect::<Result<Vec<_>>>()?;
5373	    if let Some((index, code)) = baseline_exit_codes
5374	        .iter()
5375	        .enumerate()
5376	        .find(|(_, code)| **code != 0)
5377	        .map(|(index, code)| (index, *code))
5378	    {
5379	        return Ok(MutantEvidenceRow {
5380	            id: mutant.id.clone(),
5381	            disposition: mutant.disposition.clone(),
5382	            status: "error".to_owned(),
5383	            patch: Some(patch),
5384	            runnable_tests: runnable.iter().map(|(id, _)| id.clone()).collect(),
5385	            baseline_exit_codes,
5386	            failed_tests: Vec::new(),
5387	            exit_codes: Vec::new(),
