5389	            stderr_blake3: Vec::new(),
5390	            reason: Some(format!(
5391	                "baseline witness {} exited with {code}",
5392	                runnable[index].0
5393	            )),
5394	            failure_class: Some("infrastructure".to_owned()),
5395	        });
5396	    }
5397	    if let Err(error) = apply_mutant_patch(worktree, &patch) {
5398	        return Ok(MutantEvidenceRow {
5399	            id: mutant.id.clone(),
5400	            disposition: mutant.disposition.clone(),
5401	            status: "error".to_owned(),
5402	            patch: Some(patch),
5403	            runnable_tests: runnable.iter().map(|(id, _)| id.clone()).collect(),
5404	            baseline_exit_codes,
5405	            failed_tests: Vec::new(),
5406	            exit_codes: Vec::new(),
5407	            stdout_blake3: Vec::new(),
5408	            stderr_blake3: Vec::new(),
5409	            reason: Some(error.to_string()),
5410	            failure_class: Some("infrastructure".to_owned()),
5411	        });
5412	    }
5413	    let mut failed_tests = Vec::new();
5414	    let mut exit_codes = Vec::new();
5415	    let mut stdout_blake3 = Vec::new();
5416	    let mut stderr_blake3 = Vec::new();
5417	    for (test_id, test_name) in &runnable {
5418	        let (code, stdout, stderr) = run_one_mutant_test(worktree, test_name, run_ignored)?;
5419	        exit_codes.push(code);
