5424	                id: mutant.id.clone(),
5425	                disposition: mutant.disposition.clone(),
5426	                status: "error".to_owned(),
5427	                patch: Some(patch),
5428	                runnable_tests: runnable.iter().map(|(id, _)| id.clone()).collect(),
5429	                baseline_exit_codes,
5430	                failed_tests: Vec::new(),
5431	                exit_codes,
5432	                stdout_blake3,
5433	                stderr_blake3,
5434	                reason: Some(format!(
5435	                    "mutation caused compilation failure while running {test_id}"
5436	                )),
5437	                failure_class: Some("compilation".to_owned()),
5438	            });
5439	        }
5440	        if code != 0 && !is_semantic_test_failure(test_name, &stdout, &stderr) {
