5465	        "killed"
5466	    };
5467	    Ok(MutantEvidenceRow {
5468	        id: mutant.id.clone(),
5469	        disposition: mutant.disposition.clone(),
5470	        status: status.to_owned(),
5471	        patch: Some(patch),
5472	        runnable_tests: runnable.iter().map(|(id, _)| id.clone()).collect(),
5473	        baseline_exit_codes,
5474	        failed_tests,
5475	        exit_codes,
5476	        stdout_blake3,
5477	        stderr_blake3,
5478	        reason: None,
5479	        failure_class: None,
