5749	    let mut runnable = BTreeMap::new();
5750	    let mut stack = vec![root.join("conformance"), root.join("crates")];
5751	    while let Some(dir) = stack.pop() {
5752	        let Ok(entries) = fs::read_dir(&dir) else {
5753	            continue;
5754	        };
5755	        for entry in entries.flatten() {
5756	            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
5757	                continue;
5758	            };
5759	            if path.is_dir() {
5760	                if path.file_name() != Some("target") {
5761	                    stack.push(path);
5762	                }
5763	            } else if path.extension() == Some("rs")
5764	                && let Ok(text) = fs::read_to_string(&path)
5765	            {
5766	                let mut local = BTreeMap::new();
5767	                collect_runnable_test_functions(&text, &mut local);
5768	                let prefix = path
5769	                    .strip_prefix(root.join("conformance/tests"))
5770	                    .ok()
5771	                    .and_then(|relative| {
5772	                        let mut parts = relative
5773	                            .components()
5774	                            .map(|component| component.as_str().to_owned())
5775	                            .collect::<Vec<_>>();
