5749	    let mut runnable = BTreeMap::new();
5750	    let mut stack = vec![root.join("conformance"), root.join("crates")];
5751	    while let Some(dir) = stack.pop() {
5752	        let Ok(entries) = fs::read_dir(&dir) else {
5753	            continue;
5754	        };
5755	        for entry in entries.flatten() {
5756	            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
5757	                continue;
5758	            };
5759	            if path.is_dir() {
5760	                if path.file_name() != Some("target") {
5761	                    stack.push(path);
5762	                }
5763	            } else if path.extension() == Some("rs")
5764	                && let Ok(text) = fs::read_to_string(&path)
5765	            {
5766	                let mut local = BTreeMap::new();
5767	                collect_runnable_test_functions(&text, &mut local);
5768	                let prefix = path
5769	                    .strip_prefix(root.join("conformance/tests"))
5770	                    .ok()
5771	                    .and_then(|relative| {
5772	                        let mut parts = relative
5773	                            .components()
5774	                            .map(|component| component.as_str().to_owned())
5775	                            .collect::<Vec<_>>();
5776	                        let stem = parts.pop()?.strip_suffix(".rs")?.to_owned();
5777	                        parts.push(stem);
5778	                        Some(parts.join("::"))
5779	                    });
5780	                for (leaf, count) in local {
5781	                    if let Some(prefix) = &prefix {
5782	                        runnable.insert(format!("{prefix}::{leaf}"), count);
5783	                    }
5784	                }
5785	            }
5786	        }
5787	    }
5788	
5789	    let mut missing = Vec::new();
5790	    for test in &packet.tests {
5791	        if test.name.trim().is_empty() {
5792	            anyhow::bail!("{} declares an empty test name", test.id);
5793	        }
5794	        if !runnable.contains_key(test.name.as_str()) {
5795	            missing.push(format!("{} -> {}", test.id, test.name));
5796	        } else if runnable.get(test.name.as_str()) != Some(&1) {
5797	            missing.push(format!(
5798	                "{} -> {} (module-qualified test name is ambiguous)",
5799	                test.id, test.name
5800	            ));
5801	        }
5802	    }
5803	    if !missing.is_empty() {
5804	        anyhow::bail!(
5805	            "qualification claims {} test(s) that do not exist in the tree: {}",
5806	            missing.len(),
5807	            missing.join(", ")
5808	        );
5809	    }
5810	    Ok(())
5811	}
