5813	fn collect_runnable_test_functions(text: &str, names: &mut BTreeMap<String, usize>) {
5814	    let mut test_pending = false;
5815	    let mut excluded = false;
5816	    for line in text.lines() {
5817	        let trimmed = line.trim();
5818	        if trimmed.starts_with("#[test]") {
5819	            test_pending = true;
5820	        } else if trimmed.starts_with("#[ignore")
5821	            || (trimmed.starts_with("#[cfg_attr(") && trimmed.contains("ignore"))
5822	            || cfg_attribute_excludes(trimmed)
5823	        {
5824	            // Keep an exclusion only across the attribute list immediately
5825	            // preceding one test. A module-level cfg or one ignored function
5826	            // must not poison every later runnable test in the file.
5827	            excluded = true;
5828	        } else if test_pending {
5829	            let declaration = trimmed.strip_prefix("pub ").unwrap_or(trimmed);
5830	            let declaration = declaration.strip_prefix("async ").unwrap_or(declaration);
5831	            if let Some(rest) = declaration.strip_prefix("fn ") {
5832	                if let Some(name) = rest
5833	                    .split('(')
5834	                    .next()
5835	                    .filter(|name| !name.trim().is_empty())
5836	                    && !excluded
5837	                {
5838	                    *names.entry(name.trim().to_owned()).or_default() += 1;
5839	                }
5840	                test_pending = false;
5841	                excluded = false;
5842	            }
5843	        } else if !test_pending {
5844	            // An attribute that did not lead directly to a test belongs to a
5845	            // module/helper declaration, not to the next test function.
5846	            excluded = false;
5847	        }
5848	    }
5849	}
