6622	/// Build sanitizer target from fixed source commit and compare output. Marker
6623	/// strings and self-authored logs cannot prove compiler/runtime instrumentation.
6624	/// The one path and flag set sanitizer binaries are built with, keyed by commit.
6625	///
6626	/// Must match `BUILD_ROOT` / `BUILD_RUSTFLAGS` in scripts/haqp_fuzz_campaign.sh
6627	/// verbatim; the proof records the campaign's values and the replay refuses any
6628	/// that differ, which is how the two are kept from drifting.
6629	/// The environment variable that makes a sanitizer runtime print its flags, and
6630	/// the name it prints. Closed: an unknown sanitizer is refused, not guessed.
6631	fn sanitizer_runtime_witness(sanitizer: &str) -> Result<(&'static str, &'static str)> {
6632	    Ok(match sanitizer {
6633	        "address" => ("ASAN_OPTIONS", "AddressSanitizer"),
6634	        "memory" => ("MSAN_OPTIONS", "MemorySanitizer"),
6635	        "thread" => ("TSAN_OPTIONS", "ThreadSanitizer"),
6636	        "leak" => ("LSAN_OPTIONS", "LeakSanitizer"),
6637	        other => anyhow::bail!("no runtime witness registered for sanitizer {other:?}"),
6638	    })
6639	}
