8219	    lexical_path: &Path,
8220	    lexical_lower: &str,
8221	    locked: LockedCorpus,
8222	    label: &str,
8223	) -> Result<bool> {
8224	    if lexical_path.is_absolute() {
8225	        return Ok(false);
