8238	fn resolved_corpus_paths_digest_from(
8239	    root: &Utf8Path,
8240	    trace_root: &str,
8241	    open_paths: &BTreeSet<String>,
8242	    label: &str,
8243	    access: CorpusAccess,
8244	    locked: LockedCorpus,
8245	) -> Result<String> {
8246	    let canonical_root = fs::canonicalize(root.as_std_path())
8247	        .with_context(|| format!("{label}: canonicalize repository root"))?;
8248	    let trace_root = Path::new(trace_root);
8249	    anyhow::ensure!(
8250	        trace_root.is_absolute(),
8251	        "{label}: trace_root must be absolute"
8252	    );
8253	    let mut resolved = BTreeSet::new();
8254	    for lexical in open_paths {
8255	        let lexical_path = Path::new(&lexical);
8256	        let lexical_lower = lexical_path.to_string_lossy().to_ascii_lowercase();
8257	        if relative_trace_path_is_skipped(lexical_path, &lexical_lower, locked, label)? {
8258	            continue;
8259	        }
8260	        let under_trace_root =
8261	            !lexical_path.is_absolute() || lexical_path.strip_prefix(trace_root).is_ok();
8262	        if !under_trace_root {
8263	            continue;
8264	        }
8265	        let local = trace_path_to_repo(root, trace_root, lexical)
8266	            .with_context(|| format!("{label}: cannot map traced repository path"))?;
8267	        let canonical = canonicalize_trace_path(local.as_std_path())
8268	            .with_context(|| format!("{label}: traced repository path cannot be resolved"))?;
8269	        let relative = canonical
8270	            .strip_prefix(&canonical_root)
8271	            .with_context(|| format!("{label}: traced repository path escapes repository root"))?;
8272	        let relative = relative.to_str().context("non-UTF-8 traced corpus path")?;
8273	        let lower = relative.to_ascii_lowercase();
8274	        if locked == LockedCorpus::AnyTouch {
8275	            for forbidden in FORBIDDEN_TRACE_FRAGMENTS {
8276	                anyhow::ensure!(
8277	                    !lower.contains(forbidden),
8278	                    "{label}: traced repository path resolves into forbidden data"
8279	                );
8280	            }
8281	        }
8282	        if lexical_lower.contains("/fuzz/corpus/")
8283	            || lexical_lower.starts_with("fuzz/corpus/")
8284	            || lower.contains("/fuzz/corpus/")
8285	            || lower.starts_with("fuzz/corpus/")
8286	        {
8287	            resolved.insert(format!("{lexical}\0{relative}"));
8288	        }
8289	    }
8290	    if access == CorpusAccess::Required {
8291	        anyhow::ensure!(
8292	            !resolved.is_empty(),
8293	            "{label}: trace contains no resolvable fuzz corpus path"
8294	        );
8295	    }
8296	    let resolved = resolved.into_iter().collect::<Vec<_>>();
8297	    let resolved_bytes = format!("{}\n", resolved.join("\n"));
8298	    Ok(blake3::hash(resolved_bytes.as_bytes()).to_hex().to_string())
8299	}
