8254	    for lexical in open_paths {
8255	        let lexical_path = Path::new(&lexical);
8256	        let lexical_lower = lexical_path.to_string_lossy().to_ascii_lowercase();
8257	        if relative_trace_path_is_skipped(lexical_path, &lexical_lower, locked, label)? {
