8273	        let lower = relative.to_ascii_lowercase();
8274	        if locked == LockedCorpus::AnyTouch {
8275	            for forbidden in FORBIDDEN_TRACE_FRAGMENTS {
8276	                anyhow::ensure!(
8277	                    !lower.contains(forbidden),
8278	                    "{label}: traced repository path resolves into forbidden data"
8279	                );
8280	            }
8281	        }
8282	        if lexical_lower.contains("/fuzz/corpus/")
8283	            || lexical_lower.starts_with("fuzz/corpus/")
