8341	fn trace_path_to_repo(root: &Utf8Path, trace_root: &Path, lexical: &str) -> Result<Utf8PathBuf> {
8342	    let path = Path::new(lexical);
8343	    if path.is_absolute() {
8344	        if let Ok(relative) = path.strip_prefix(trace_root) {
8345	            return Ok(
8346	                root.join(Utf8Path::from_path(relative).context("non-UTF-8 traced relative path")?)
8347	            );
8348	        }
8349	        anyhow::bail!("absolute traced path is outside recorded trace root")
8350	    }
8351	    Ok(root.join(Utf8Path::from_path(path).context("non-UTF-8 traced relative path")?))
8352	}
