7760	fn scan_scope_trace<R: std::io::BufRead>(mut reader: R) -> Result<ScopeTraceScan> {
7761	    let mut scan = ScopeTraceScan::default();
7762	    let mut hasher = blake3::Hasher::new();
7763	    let mut buf = Vec::new();
