7765	    // followed by `openat(7, "x.md", O_WRONLY)` named the locked corpus only on
7766	    // the permitted read; the write carried no fragment. Directory fds are
7767	    // remembered per pid from their open's return value, and a path relative
7768	    // to one is judged under that directory. An `<unfinished ...>` open is
7769	    // completed by its `<... openat resumed>) = fd` line.
7770	    let mut open_fds: BTreeMap<(u32, i64), String> = BTreeMap::new();
7771	    let mut unfinished: BTreeMap<u32, (String, bool)> = BTreeMap::new();
