7773	    // every later relative write nameless — no fragment, and resolution
7774	    // against the repository root put it somewhere harmless. The cwd each pid
7775	    // announces is remembered, and its relative paths resolve there.
7776	    let mut cwds: BTreeMap<u32, String> = BTreeMap::new();
