7843	        // open's path is already remembered for its fd, so the descriptor
7844	        // resolves to the file it names.
7845	        if let Some(pid) = pid
7846	            && let Some(path) = fd_write_target(&line, pid, &open_fds)
7847	        {
7848	            accesses.push((path, true));
7849	        }
7850	        if let Some(pid) = pid {
7851	            // Blind pass 1 at e09ae5e (A07): the cwd and dirfd maps are keyed
7852	            // per pid and were never inherited, so a parent that chdir'd into
7853	            // the locked corpus and then forked left the CHILD unanchored —
7854	            // its relative write carried no forbidden text and resolved
7855	            // against nothing. A child begins life with its parent's working
7856	            // directory and its open descriptors.
7857	            if let Some(child) = clone_child_pid(&line) {
7858	                // A parent with no recorded cwd is at the trace's root, and so
7859	                // is its child: whatever the map held for the child's number
7860	                // belonged to an earlier process (A06, `cbed339f`).
7861	                match cwds.get(&pid).cloned() {
7862	                    Some(cwd) => cwds.insert(child, cwd),
7863	                    None => cwds.remove(&child),
7864	                };
7865	                let inherited = open_fds
7866	                    .range((pid, i64::MIN)..=(pid, i64::MAX))
7867	                    .map(|((_, fd), dir)| (*fd, dir.clone()))
7868	                    .collect::<Vec<_>>();
7869	                for (fd, dir) in inherited {
7870	                    open_fds.insert((child, fd), dir);
7871	                }
7872	            }
7873	            record_chdir(&line, pid, &open_fds, &mut cwds);
7874	            record_duplicated_fd(&line, pid, returned_fd, &mut open_fds);
7875	            // Blind pass 1 at 5fb1b57 (A10): only `O_DIRECTORY` opens were
7876	            // remembered, so a descriptor opened without it and later used as
7877	            // a dirfd resolved against nothing. Every successful open's path
7878	            // is remembered for its fd; one that is not a directory simply
7879	            // never appears as a dirfd.
7880	            if (line.contains("openat(") || line.contains("openat2(") || line.contains(" open("))
7881	                && let Some((path, _)) = accesses.first()
7882	            {
7883	                if line.contains("<unfinished ...>") {
7884	                    unfinished.insert(pid, (path.clone(), true));
7885	                } else if let Some(fd) = returned_fd {
7886	                    if fd >= 0 {
7887	                        open_fds.insert((pid, fd), path.clone());
7888	                    } else {
7889	                        open_fds.remove(&(pid, fd));
7890	                    }
7891	                }
7892	            }
7893	        }
7894	        for (path, write) in accesses {
7895	            // Blind pass 1 at `6b36bbb9` (A02): candidates were collected only
7896	            // when the path LOOKED like the corpus, so F-64's inode comparison
7897	            // — added for exactly the case where it does not — never saw a
7898	            // hard link under an unrelated name. Every write is a candidate;
7899	            // the lexical rules still decide the lexical cases, and identity
7900	            // decides the rest.
7901	            if write {
7902	                scan.locked_write_candidates.push(path.clone());
7903	            }
7904	            // Failed lookups remain write candidates above, so an attempted
7905	            // mutation of locked data still refuses. They are excluded from
7906	            // open-path and resolution digests: no kernel object was opened,
7907	            // and canonicalization cannot authenticate a path that never
7908	            // existed (ENOENT probes are common in tool discovery).
7909	            if !scope_trace_line_failed(&line) {
7910	                scan.open_paths.insert(path);
7911	            }
7912	        }
7913	    }
7914	    scan.raw_blake3 = hasher.finalize().to_hex().to_string();
7915	    Ok(scan)
7916	}
