7918	/// Stream a stored trace, `.zst` accepted, without holding it whole.
7919	fn open_evidence_reader(path: &Utf8Path) -> Result<Box<dyn std::io::BufRead>> {
7920	    let file = fs::File::open(path).with_context(|| format!("open {path}"))?;
7921	    if path.extension() == Some("zst") {
7922	        let decoder = zstd::Decoder::new(file)
7923	            .with_context(|| format!("{path}: evidence is not valid zstd"))?;
7924	        // The decoder buffers its input; the outer BufReader is for read_until.
7925	        Ok(Box::new(std::io::BufReader::new(decoder)))
