7931	/// F-44 ruling (Brian, 2026-09-05). A stage may READ the locked corpus -- the
7932	/// SLO graduation test measures the profile on it, which is why it is held
7933	/// out -- but no stage may modify the repository's copy of it: the "never
7934	/// hash-update" half of the lock, enforced on every trace. Copies under build
7935	/// roots and scratch directories are outside the repository. The carved fuzz
7936	/// binaries keep the full rule: their traces may not carry the fragment at
7937	/// all (`ScopeTraceScan::forbidden`), because they are the one process family
7938	/// whose evidence is about the corpus.
7939	///
7940	/// Relative paths are judged root-relative, conservatively: a stage's cwd is
7941	/// not receipted, so a relative write that names the locked corpus refuses.
7942	/// Every (device, inode) under the locked corpus. Blind pass 1 at `aeed70f9`
7943	/// (A07): the write check resolved symlinks and pathname ancestry, and a hard
7944	/// link is neither — it is a second name for the same inode, so writing
7945	/// through one outside the corpus mutates corpus bytes under an innocent path.
7946	/// Identity is read from directory metadata; no corpus file is opened.
7947	fn locked_corpus_identities(root: &Utf8Path, within: &str) -> Result<BTreeSet<(u64, u64)>> {
7948	    use std::os::unix::fs::MetadataExt as _;
7949	    let corpora = root.join(within);
7950	    let mut identities = BTreeSet::new();
7951	    if !corpora.is_dir() {
7952	        return Ok(identities);
7953	    }
7954	    let mut stack = vec![corpora];
7955	    while let Some(dir) = stack.pop() {
7956	        // Review of `bba803d4`: skipping an unreadable directory returned a
7957	        // partial set, and a hard link to a file inside it would then pass. A
7958	        // corpus this cannot enumerate is a corpus it cannot protect.
7959	        let entries = fs::read_dir(dir.as_std_path())
7960	            .with_context(|| format!("enumerate the locked corpus at {dir}"))?;
7961	        for entry in entries.flatten() {
7962	            let path = entry.path();
7963	            let metadata = fs::symlink_metadata(&path)
7964	                .with_context(|| format!("stat {} in the locked corpus", path.display()))?;
7965	            if metadata.is_dir() {
7966	                if let Ok(dir) = Utf8PathBuf::from_path_buf(path) {
7967	                    stack.push(dir);
7968	                }
7969	            } else if metadata.is_file() {
7970	                identities.insert((metadata.dev(), metadata.ino()));
7971	            }
7972	        }
7973	    }
7974	    Ok(identities)
7975	}
