7977	fn locked_corpus_write(
7978	    root: &Utf8Path,
7979	    candidates: &[String],
7980	    label: &str,
7981	) -> Result<Option<String>> {
7982	    let canonical_root = fs::canonicalize(root.as_std_path())
7983	        .with_context(|| format!("{label}: canonicalize repository root"))?;
7984	    let identities = locked_corpus_identities(root, "conformance/corpora")?;
7985	    for lexical in candidates {
7986	        let path = Path::new(lexical);
7987	        // Blind pass 1 at 78c8f9b (A12): a relative write from a subdirectory,
7988	        // `../conformance/corpora/heldout/x`, joined onto the root climbed out
7989	        // of it and passed. The cwd is not receipted, so a relative write that
7990	        // names the locked corpus at all is refused, before any resolution.
7991	        let lower = lexical.to_ascii_lowercase();
7992	        if !path.is_absolute()
7993	            && (lower.contains("conformance/corpora/") || lower.ends_with("conformance/corpora"))
7994	        {
7995	            return Ok(Some(lexical.clone()));
7996	        }
7997	        let local = if path.is_absolute() {
7998	            path.to_path_buf()
7999	        } else {
8000	            root.as_std_path().join(path)
8001	        };
8002	        // A path that no longer resolves (deleted after the trace) is judged
8003	        // lexically: the conservative direction, since a lexical
8004	        // conformance/corpora prefix still refuses.
8005	        let canonical = canonicalize_trace_path(&local).unwrap_or(local);
8006	        if let Ok(relative) = canonical.strip_prefix(&canonical_root)
8007	            && relative
8008	                .to_string_lossy()
8009	                .to_ascii_lowercase()
8010	                .starts_with("conformance/corpora")
8011	        {
8012	            return Ok(Some(lexical.clone()));
8013	        }
8014	        // A07: a hard link is a second name for the same inode, so no amount
8015	        // of path reasoning sees it. Identity does.
8016	        if let Ok(metadata) = fs::symlink_metadata(&canonical) {
8017	            use std::os::unix::fs::MetadataExt as _;
8018	            if identities.contains(&(metadata.dev(), metadata.ino())) {
8019	                return Ok(Some(format!(
8020	                    "{lexical} (hard link into the locked corpus)"
8021	                )));
8022	            }
8023	        }
8024	    }
8025	    Ok(None)
8026	}
