8042	/// Scan a scope's stored remainder and every carved part, binding each part's
8043	/// bytes to the digest the row declares. Returns the remainder's scan and the
8044	/// union of open paths; a locked-corpus fragment in ANY file is the row's.
8045	/// Whether any of `paths` names a file the locked corpus also names. A hard
8046	/// link is a second name for one inode, so no amount of path reasoning sees it.
8047	fn corpus_identity_touched(root: &Utf8Path, paths: &BTreeSet<String>) -> Result<bool> {
8048	    use std::os::unix::fs::MetadataExt as _;
8049	    let identities = locked_corpus_identities(root, "conformance/corpora")?;
8050	    if identities.is_empty() {
8051	        return Ok(false);
8052	    }
8053	    for path in paths {
8054	        let local = if Path::new(path).is_absolute() {
8055	            std::path::PathBuf::from(path)
8056	        } else {
8057	            root.as_std_path().join(path)
8058	        };
8059	        let resolved = canonicalize_trace_path(&local).unwrap_or(local);
8060	        if let Ok(metadata) = fs::symlink_metadata(&resolved)
8061	            && identities.contains(&(metadata.dev(), metadata.ino()))
8062	        {
8063	            return Ok(true);
8064	        }
8065	    }
8066	    Ok(false)
8067	}
