8069	fn scan_scope_trace_union(
8070	    root: &Utf8Path,
8071	    row: &CorpusScopeTrace,
8072	) -> Result<(ScopeTraceScan, BTreeSet<String>, Option<&'static str>)> {
8073	    let label = format!("{} corpus scope", row.scope);
8074	    let remainder_path = safe_repo_path(root, &row.trace, "corpus scope trace")?;
8075	    let remainder = scan_scope_trace_file(&remainder_path, &label)?;
8076	    let mut open = remainder.open_paths.clone();
8077	    // The remainder is a stage: reads permitted, writes judged by the caller
8078	    // (F-44). Parts are the fuzz binaries: any fragment refuses.
8079	    let mut forbidden = None;
8080	    for part in &row.parts {
8081	        let part_path = safe_repo_path(root, &part.trace, "corpus scope trace part")?;
8082	        let scan = scan_scope_trace_file(&part_path, &label)?;
8083	        require_eq(
8084	            &format!(
8085	                "{} corpus scope part {} trace_blake3",
8086	                row.scope, part.trace
8087	            ),
8088	            &part.trace_blake3,
8089	            &scan.raw_blake3,
8090	        )?;
8091	        forbidden = forbidden.or(scan.forbidden);
8092	        // Blind pass 1 at `0a0b4b4b` (A07): the any-touch rule fired on the
8093	        // lexical fragments `heldout` and `conformance/corpora`, so a hard
8094	        // link under any other name was invisible — and F-64's inode
8095	        // comparison guarded writes only, while the carved fuzz binaries are
8096	        // the one family for which a READ is the leak. Identity applies to
8097	        // every path a fuzz part opened.
8098	        if forbidden.is_none() && corpus_identity_touched(root, &scan.open_paths)? {
8099	            forbidden = Some("locked corpus reached by inode identity");
8100	        }
8101	        open.extend(scan.open_paths);
8102	    }
8103	    Ok((remainder, open, forbidden))
8104	}
