8301	/// Canonicalize the existing prefix of a traced path, then append historical
8302	/// leaf components that libFuzzer may have deleted after opening them. This
8303	/// preserves symlink and root-boundary checks without requiring every path in
8304	/// a long-running trace to remain present at receipt time.
8305	fn canonicalize_trace_path(path: &Path) -> Result<std::path::PathBuf> {
8306	    let mut missing = Vec::new();
8307	    let mut cursor = path;
8308	    loop {
8309	        match fs::symlink_metadata(cursor) {
8310	            Ok(_) => break,
8311	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
8312	                missing.push(
8313	                    cursor
8314	                        .file_name()
8315	                        .context("traced path has no recoverable leaf")?
8316	                        .to_owned(),
8317	                );
8318	                let leaf = missing.last().expect("just pushed missing leaf");
8319	                anyhow::ensure!(
8320	                    leaf != std::ffi::OsStr::new(".") && leaf != std::ffi::OsStr::new(".."),
8321	                    "traced path contains a parent-directory suffix"
8322	                );
8323	                cursor = cursor
8324	                    .parent()
8325	                    .context("traced path has no existing ancestor")?;
8326	                anyhow::ensure!(
8327	                    cursor.file_name() != Some(std::ffi::OsStr::new("corpus")),
8328	                    "traced path is missing a corpus entry; symlink history is unavailable"
8329	                );
8330	            }
8331	            Err(error) => return Err(error.into()),
8332	        }
8333	    }
8334	    let mut canonical = fs::canonicalize(cursor)?;
8335	    for component in missing.into_iter().rev() {
8336	        canonical.push(component);
8337	    }
8338	    Ok(canonical)
8339	}
