8590	/// Check the bounded-campaign clock artifact. One clean breach is retained as
8591	/// residual risk; two clean breaches block ratification per ADR-0020 §7.
8592	/// Days from 1970-01-01 for a civil date (Howard Hinnant's algorithm). Used to
8593	/// turn a provider's ISO timestamp into an epoch without taking a date
8594	/// dependency for one calculation.
8595	fn days_from_civil(year: i64, month: i64, day: i64) -> i64 {
8596	    let year = if month <= 2 { year - 1 } else { year };
8597	    let era = if year >= 0 { year } else { year - 399 } / 400;
8598	    let year_of_era = year - era * 400;
8599	    let month_shift = if month > 2 { month - 3 } else { month + 9 };
8600	    let day_of_year = (153 * month_shift + 2) / 5 + day - 1;
8601	    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
8602	    era * 146_097 + day_of_era - 719_468
8603	}
