8605	/// The epoch second in a codex session id, which opens
8606	/// `YYYY-MM-DDTHH-MM-SS-<uuid>`. The provider's CLI writes it, not the
8607	/// qualifier.
8608	fn codex_session_epoch(session_id: &str) -> Option<i64> {
8609	    let digits: Vec<i64> = session_id
8610	        .split(['-', 'T'])
8611	        .take(6)
8612	        .map(|part| part.parse::<i64>().ok())
8613	        .collect::<Option<Vec<_>>>()?;
8614	    let [year, month, day, hour, minute, second] = digits[..] else {
8615	        return None;
8616	    };
8617	    if !(1..=12).contains(&month) || !(1..=31).contains(&day) || hour > 23 || minute > 59 {
8618	        return None;
8619	    }
8620	    Some(days_from_civil(year, month, day) * 86_400 + hour * 3_600 + minute * 60 + second)
8621	}
